export const getProgressTone = (progress: number, isDark: boolean = false): string => {
  if (progress >= 100) return"emerald";
  if (progress >= 80) return"amber";
  if (progress >= 50) return"yellow";
  if (progress >= 25) return"orange";
  return"rose";
};

export const getProgressBgClass = (progress: number, isDark: boolean = false): string => {
  if (isDark) {
    if (progress >= 100) return"bg-emerald-400";
    if (progress >= 80) return"bg-amber-400";
    if (progress >= 50) return"bg-yellow-400";
    if (progress >= 25) return"bg-orange-400";
    return"bg-rose-400";
  }
  if (progress >= 100) return"bg-emerald-500";
  if (progress >= 80) return"bg-amber-500";
  if (progress >= 50) return"bg-yellow-500";
  if (progress >= 25) return"bg-orange-500";
  return"bg-rose-500";
};

export const getDaysProgressColor = (progress: number, isDark: boolean = false): string => {
  if (isDark) {
    if (progress >= 90) return"bg-rose-400";
    if (progress >= 70) return"bg-amber-400";
    if (progress >= 50) return"bg-yellow-400";
    return"bg-emerald-400";
  }
  if (progress >= 90) return"bg-rose-500";
  if (progress >= 70) return"bg-amber-500";
  if (progress >= 50) return"bg-yellow-500";
  return"bg-emerald-500";
};

// 🔑 توابع محاسباتی قرارداد
interface TariffLike {
  rate: string | number;
  consumed_quantity?: number;
  total_quantity?: number;
  invoiced?: number;
  contract_id?: string;
}

interface ContractLike {
  id: string;
  total_value: number;
  start_date: string;
  end_date: string;
  invoiced: number;
  status: string;
  currency?: string;
  financial_terms?: {
    adjustment?: {
      enabled?: boolean;
      effective_date?: string;
      mode?:"FIXED"|"TBD";
      percentage?: number;
    };
  };
}

export const calculateProgressFromTariffs = (contract: ContractLike): number => {
  const tariffs = contractTariffs.filter((t) => t.contract_id === contract.id);
  if (tariffs.length === 0) return 0;
  if (contract.total_value <= 0) return 0;
  const totalPerformed = tariffs.reduce((sum, t) => {
    const rate = typeof t.rate ==='string'? parseNumberInput(t.rate) : (t.rate || 0);
    const consumed = t.consumed_quantity || 0;
    return sum + (rate * consumed);
  }, 0);
  return (totalPerformed / contract.total_value) * 100;
};

export const calculateInvoiceProgress = (contract: ContractLike): number => {
  const tariffs = contractTariffs.filter((t) => t.contract_id === contract.id);
  if (tariffs.length === 0) return 0;
  const totalInvoiced = tariffs.reduce((sum, t) => sum + (t.invoiced || 0), 0);
  const performedWork = tariffs.reduce((sum, t) => {
    const rate = typeof t.rate ==='string'? parseNumberInput(t.rate) : (t.rate || 0);
    const consumed = t.consumed_quantity || 0;
    return sum + (rate * consumed);
  }, 0);
  if (performedWork <= 0) return 0;
  return (totalInvoiced / performedWork) * 100;
};

export const calculateDaysProgress = (contract: ContractLike): number => {
  if (!contract.start_date || !contract.end_date) return 0;
  const [startJy, startJm, startJd] = contract.start_date.split('/').map(Number);
  const [endJy, endJm, endJd] = contract.end_date.split('/').map(Number);
  const startG = jalaali.toGregorian(startJy, startJm, startJd);
  const endG = jalaali.toGregorian(endJy, endJm, endJd);
  const startDate = new Date(startG.gy, startG.gm - 1, startG.gd);
  const endDate = new Date(endG.gy, endG.gm - 1, endG.gd);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const totalDays = (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24);
  const daysPassed = (today.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24);
  if (totalDays <= 0) return 0;
  if (daysPassed <= 0) return 0;
  if (daysPassed >= totalDays) return 100;
  return (daysPassed / totalDays) * 100;
};

export const calculateDaysLeft = (endDate: string): number => {
  if (!endDate) return 0;
  const [jy, jm, jd] = endDate.split('/').map(Number);
  const gDate = jalaali.toGregorian(jy, jm, jd);
  const endGregorian = new Date(gDate.gy, gDate.gm - 1, gDate.gd);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const diffTime = endGregorian.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

export const getDaysUntilStart = (startDate: string): number => {
  if (!startDate) return 0;
  const [jy, jm, jd] = startDate.split('/').map(Number);
  const gDate = jalaali.toGregorian(jy, jm, jd);
  const startGregorian = new Date(gDate.gy, gDate.gm - 1, gDate.gd);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const diffTime = startGregorian.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

export const isContractNotStarted = (startDate: string): boolean => {
  if (!startDate) return false;
  const [jy, jm, jd] = startDate.split('/').map(Number);
  const gDate = jalaali.toGregorian(jy, jm, jd);
  const startGregorian = new Date(gDate.gy, gDate.gm - 1, gDate.gd);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return startGregorian.getTime() > today.getTime();
};

export const calculateBudgetSpent = (totalValue: number, invoiced: number): number => {
  if (totalValue <= 0) return 0;
  return (invoiced / totalValue) * 100;
};

// 🔑 توابع محاسباتی مشتریان (برای Clients.tsx)
export const calculatePerformedWorkValue = (tariffs: TariffLike[]): number => {
  return tariffs.reduce((sum, t) => {
    const rate = typeof t.rate ==='string'? parseNumberInput(t.rate) : (t.rate || 0);
    const consumed = t.consumed_quantity || 0;
    return sum + (rate * consumed);
  }, 0);
};

export const calculateTotalInvoicedFromTariffs = (tariffs: TariffLike[]): number => {
  return tariffs.reduce((sum, t) => sum + (t.invoiced || 0), 0);
};

export const calculateUninvoicedWork = (tariffs: TariffLike[]): number => {
  const performed = calculatePerformedWorkValue(tariffs);
  const invoiced = calculateTotalInvoicedFromTariffs(tariffs);
  return Math.max(0, performed - invoiced);
};

// 🔑 توابع Contracts-specific (قبلاً فقط در Contracts.tsx بودن)

// محاسبه اولین روز سال شمسی بعد از تاریخ شروع قرارداد
export const getNextJalaaliYearStart = (startDate: string): string => {
  if (!startDate) return"";
  const [jy, jm, jd] = startDate.split('/').map(Number);
  if (!jy) return"";
  const nextYear = jy + 1;
  return `${nextYear}/01/01`;
};

// محاسبه سال جلالی فعلی
export const getCurrentJalaaliYear = (): number => {
  const now = new Date();
  const j = jalaali.toJalaali(now.getFullYear(), now.getMonth() + 1, now.getDate());
  return j.jy;
};

// تولید شماره قرارداد
export const generateContractNo = (
  type:"CONTRACT"|"WORK_ORDER",
  contracts: ContractLike[],
  department: string ="Unit A"): string => {
  const year = getCurrentJalaaliYear();
  const prefix = type ==="CONTRACT"?"CTR":"WO";
  const deptCode = department ==="Unit A"?"UNA":"DEPT";
  const count = contracts.filter((c) => c.status !=="COMPLETED").length + 1;
  return `${prefix}-${deptCode}-${year}-${String(count).padStart(4,"0")}`;
};

// وضعیت مالی قرارداد
export const getContractFinancialStatus = (contract: ContractLike):"completed"|"needs_review"|"active"|"not_started"=> {
  const daysLeft = calculateDaysLeft(contract.end_date);
  const daysUntilStart = getDaysUntilStart(contract.start_date);
  const notStarted = daysUntilStart > 0;
  const isExpired = daysLeft < 0;
  const isFullyInvoiced = contract.invoiced >= contract.total_value;
  
  if (contract.status ==="COMPLETED") return"completed";
  if (notStarted) return"not_started";
  if (isExpired && isFullyInvoiced) return"completed";
  if (isExpired && !isFullyInvoiced) return"needs_review";
  return"active";
};

// یادآوری تعدیل (۳۰ روز قبل از تاریخ اعمال)
export const getAdjustmentReminder = (contract: ContractLike): {
  show: boolean;
  daysUntil: number;
  mode:"FIXED"|"TBD";
  percentage: number;
  effectiveDate: string;
} => {
  if (!contract.financial_terms?.adjustment?.enabled) {
    return { show: false, daysUntil: 0, mode:"FIXED", percentage: 0, effectiveDate:""};
  }

  const adjustment = contract.financial_terms.adjustment;
  if (!adjustment.effective_date) {
    return { show: false, daysUntil: 0, mode: adjustment.mode ||"FIXED", percentage: adjustment.percentage || 0, effectiveDate:""};
  }

  const daysUntil = getDaysUntilStart(adjustment.effective_date);
  const shouldShow = daysUntil > 0 && daysUntil <= 30;

  return {
    show: shouldShow,
    daysUntil,
    mode: adjustment.mode ||"FIXED",
    percentage: adjustment.percentage || 0,
    effectiveDate: adjustment.effective_date,
  };
};

// آیا قرارداد در آستانه پایان هست؟
export const isExpiringSoon = (contract: ContractLike): { expiring: boolean; daysLeft: number } => {
  if (contract.status !=="ACTIVE") return { expiring: false, daysLeft: 0 };
  const daysLeft = calculateDaysLeft(contract.end_date);
  const daysUntilStart = getDaysUntilStart(contract.start_date);
  if (daysUntilStart > 0 || daysLeft <= 0) return { expiring: false, daysLeft };
  return { expiring: daysLeft <= 132, daysLeft };
};

// نوع نیاز به بررسی
export const getNeedsReviewType = (contract: ContractLike): {
  type:"value_review"|"invoice_review"|"time_review"|"none";
  message: string;
  details: string;
} => {
  const daysLeft = calculateDaysLeft(contract.end_date);
  const isExpired = daysLeft < 0;

  const tariffs = contractTariffs.filter((t) => t.contract_id === contract.id);
  const performedWork = tariffs.reduce((sum, t) => {
    const rate = typeof t.rate ==='string'? parseNumberInput(t.rate) : (t.rate || 0);
    const consumed = t.consumed_quantity || 0;
    return sum + (rate * consumed);
  }, 0);

  const totalInvoiced = tariffs.reduce((sum, t) => sum + (t.invoiced || 0), 0);
  const invoicePercentage = performedWork > 0 ? (totalInvoiced / performedWork) * 100 : 0;

  if (performedWork > contract.total_value && !isExpired) {
    const overAmount = performedWork - contract.total_value;
    return {
      type:"value_review",
      message:"Total Agreement Value Review",
      details: `Performed work (${formatCurrency(performedWork, contract.currency ||"IRR")}) exceeds total contract value (${formatCurrency(contract.total_value, contract.currency ||"IRR")}) by ${formatCurrency(overAmount, contract.currency ||"IRR")}`
    };
  }

  if (invoicePercentage > 110) {
    return {
      type:"invoice_review",
      message:"Invoice Review Required",
      details: `Invoiced amount (${formatCurrency(totalInvoiced, contract.currency ||"IRR")}) is ${invoicePercentage.toFixed(1)}% of performed work (${formatCurrency(performedWork, contract.currency ||"IRR")}). This exceeds the 110% threshold.`
    };
  }

  if (isExpired && contract.invoiced <= contract.total_value && invoicePercentage <= 110) {
    const daysOverdue = Math.abs(daysLeft);
    return {
      type:"time_review",
      message:"Time Review Required",
      details: `Contract expired ${daysOverdue} days ago. Please review and decide whether to extend or complete the contract.`
    };
  }

  return { type:"none", message:"", details:""};
};

// درصد صورتحساب
export const getInvoicedPercentage = (contract: ContractLike): number => {
  if (contract.total_value <= 0) return 0;
  return (contract.invoiced / contract.total_value) * 100;
};

// src/components/TariffEditor.tsx
import { useState, useMemo } from'react';
import { Button, Badge } from"@design-system";
import { useTheme } from'@app/providers/ThemeProvider';
import { formatNumberInput, parseNumberInput } from'@entities/contract/services/contractCalculations';

// 🔑 Types
export interface TariffLine {
  id: string;
  contract_id?: string;
  description: string;
  unit: string;
  rate: string | number;
  currency?: string;
  total?: number;
  isLumpSum?: boolean;
  total_quantity?: number;
  consumed_quantity?: number;
  invoiced?: number;
}

export interface TariffEditorProps {
  tariffs: TariffLine[];
  onChange: (tariffs: TariffLine[]) => void;
  error?: string;
  showTotals?: boolean;
}

const CURRENCIES = ['IRR','USD','EUR'];
const UNITS = ['MAN_DAY','DOCUMENT','VESSEL','LUMP_SUM'];

export function TariffEditor({ tariffs, onChange, error, showTotals = true }: TariffEditorProps) {
  const { isDark } = useTheme();

  const addTariff = () => {
    const newTariff: TariffLine = {
      id: `t${Date.now()}`,
      description:'',
      unit:'MAN_DAY',
      rate:'',
      currency:'IRR',
      total: 0,
      isLumpSum: false,
    };
    onChange([...tariffs, newTariff]);
  };

  const removeTariff = (id: string) => {
    if (tariffs.length <= 1) return;
    onChange(tariffs.filter((t) => t.id !== id));
  };

  const updateTariff = (id: string, field: keyof TariffLine, value: any) => {
    const updated = tariffs.map((t) => {
      if (t.id !== id) return t;
      const newTariff = { ...t, [field]: value };
      if (field ==='rate') {
        newTariff.total = parseNumberInput(newTariff.rate as string);
      }
      if (field ==='isLumpSum'&& value === true) {
        newTariff.unit ='LUMP_SUM';
      }
      return newTariff;
    });
    onChange(updated);
  };

  const totalsByCurrency = useMemo(() => {
    const totals: Record<string, number> = {};
    tariffs.forEach((t) => {
      const curr = t.currency ||'IRR';
      if (!totals[curr]) totals[curr] = 0;
      totals[curr] += t.total || parseNumberInput(t.rate as string);
    });
    return totals;
  }, [tariffs]);

  return (
    <div>
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <h3 className="text-sm font-semibold text-primary">Tariff Lines</h3>
          <Badge tone="indigo">{tariffs.length}</Badge>
        </div>
        <Button
          type="button"variant="outline"size="sm"onClick={addTariff}
          className="gap-1.5 text-xs">
          ➕ Add Tariff
        </Button>
      </div>

      {error && (
        <div className="mb-3 rounded-lg border border-rose-200 bg-rose-50 p-2 text-xs font-medium text-rose-700">
          ✕ {error}
        </div>
      )}

      <div className="space-y-2">
        {tariffs.map((tariff, index) => (
          <div
            key={tariff.id}
            className={`rounded-lg border p-3 ${
              tariff.isLumpSum
                ? (isDark ?'border-indigo-700 bg-indigo-900/20':'border-indigo-200 bg-indigo-50/30')
                : (isDark ?'border-slate-700 bg-muted/50':'border-slate-200 bg-muted/50')
            }`}
          >
            <div className="flex items-center gap-2 mb-2">
              <span className="text-xs font-semibold text-secondary">#{index + 1}</span>
              {tariff.isLumpSum && <Badge tone="indigo">Lump Sum</Badge>}
              <div className="flex-1"/>
              {tariffs.length > 1 && (
                <button
                  type="button"onClick={() => removeTariff(tariff.id)}
                  className="p-1 text-rose-600 hover:bg-rose-100 rounded transition-colors"title="Remove">
                  🗑️
                </button>
              )}
            </div>

            <div className="grid grid-cols-12 gap-2">
              <div className="col-span-6">
                <input
                  type="text"value={tariff.description}
                  onChange={(e) => updateTariff(tariff.id,'description', e.target.value)}
                  placeholder="Description..."className="w-full rounded border px-2 py-1.5 text-xs input-themed"/>
              </div>

              <div className="col-span-2">
                <select
                  value={tariff.unit}
                  onChange={(e) => updateTariff(tariff.id,'unit', e.target.value)}
                  className="w-full rounded border px-2 py-1.5 text-xs input-themed">
                  {UNITS.map((u) => (
                    <option key={u} value={u}>
                      {u ==='MAN_DAY'?'Man Day': u ==='DOCUMENT'?'Document': u ==='VESSEL'?'Vessel':'Lump Sum'}
                    </option>
                  ))}
                </select>
              </div>

              <div className="col-span-3">
                <input
                  type="text"inputMode="numeric"value={tariff.rate}
                  onChange={(e) => updateTariff(tariff.id,'rate', formatNumberInput(e.target.value))}
                  className="w-full rounded border px-2 py-1.5 text-xs font-mono text-right input-themed [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"placeholder="Rate"/>
              </div>

              <div className="col-span-1">
                <select
                  value={tariff.currency}
                  onChange={(e) => updateTariff(tariff.id,'currency', e.target.value)}
                  className="w-full rounded border px-1 py-1.5 text-[10px] font-semibold input-themed">
                  {CURRENCIES.map((c) => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showTotals && Object.keys(totalsByCurrency).length > 0 && (
        <div className="mt-3 space-y-2">
          <div className="text-xs font-semibold text-primary mb-2">Totals by Currency:</div>
          {Object.entries(totalsByCurrency).map(([currency, total]) => (
            <div
              key={currency}
              className={`flex items-center justify-between rounded-lg border p-3 ${
                isDark ?'border-slate-700 bg-muted':'border-slate-200 bg-muted'}`}
            >
              <div className="flex items-center gap-2">
                <Badge tone="indigo">{currency}</Badge>
                <span className="text-sm font-semibold text-primary">Total:</span>
              </div>
              <span className="text-lg font-bold text-accent-emerald">
                {total.toLocaleString('en-US')}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// src/features/audit-log/ui/AuditLogDetailModal.tsx
import { AuditLogEntry } from '../types';
import { formatAuditValue, formatFieldName } from '../utils/formatAuditValue';

interface Props {
  log: AuditLogEntry;
  onClose: () => void;
}

const levelBorderColors = {
  info: 'border-blue-500',
  warning: 'border-yellow-500',
  error: 'border-red-500',
  success: 'border-green-500',
};

const levelBgColors = {
  info: 'bg-blue-50 dark:bg-blue-900/20',
  warning: 'bg-yellow-50 dark:bg-yellow-900/20',
  error: 'bg-red-50 dark:bg-red-900/20',
  success: 'bg-green-50 dark:bg-green-900/20',
};

/**
 * نمایش یک تغییر فیلد به شکل human-readable
 */
function FieldChangeDisplay({ fieldChange }: { fieldChange: any }) {
  const { field, before, after, diff } = fieldChange;
  const fieldName = formatFieldName(field);

  // اگر فیلد آرایه هست و deep diff داره
  if (diff && diff.type === 'array') {
    return (
      <div className="bg-white dark:bg-slate-800 rounded-lg p-4 border border-slate-200 dark:border-slate-700">
        <div className="text-sm font-bold text-slate-900 dark:text-slate-100 mb-3 flex items-center gap-2">
          <span className="bg-indigo-100 dark:bg-indigo-900 text-indigo-800 dark:text-indigo-200 px-2 py-0.5 rounded text-xs font-mono">
            {fieldName}
          </span>
          <span className="text-xs text-slate-500 dark:text-slate-400">(Array)</span>
        </div>

        <div className="space-y-3">
          {/* Added Items */}
          {diff.added && diff.added.length > 0 && (
            <div>
              <div className="text-xs font-semibold text-green-600 dark:text-green-400 mb-2">
                ➕ Added ({diff.added.length})
              </div>
              <div className="space-y-1">
                {diff.added.map((item: any, idx: number) => (
                  <div key={idx} className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded p-2">
                    <div className="text-sm text-slate-900 dark:text-slate-100">
                      {formatAuditValue(item)}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Removed Items */}
          {diff.removed && diff.removed.length > 0 && (
            <div>
              <div className="text-xs font-semibold text-red-600 dark:text-red-400 mb-2">
                🗑️ Removed ({diff.removed.length})
              </div>
              <div className="space-y-1">
                {diff.removed.map((item: any, idx: number) => (
                  <div key={idx} className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded p-2">
                    <div className="text-sm text-slate-900 dark:text-slate-100 line-through opacity-70">
                      {formatAuditValue(item)}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Updated Items */}
          {diff.updated && diff.updated.length > 0 && (
            <div>
              <div className="text-xs font-semibold text-blue-600 dark:text-blue-400 mb-2">
                ️ Updated ({diff.updated.length})
              </div>
              {diff.updated.map((change: any, idx: number) => (
                <div key={idx} className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded p-3">
                  <div className="text-xs font-semibold text-blue-900 dark:text-blue-200 mb-2">
                    {formatAuditValue(change.after)}
                  </div>
                  {change.fieldChanges && change.fieldChanges.length > 0 && (
                    <div className="space-y-1 mt-2">
                      {change.fieldChanges.map((fc: any, fIdx: number) => (
                        <div key={fIdx} className="grid grid-cols-2 gap-2 text-xs">
                          <div className="text-red-700 dark:text-red-300 bg-red-50 dark:bg-red-900/30 p-1 rounded">
                            {formatAuditValue(fc.before)}
                          </div>
                          <div className="text-green-700 dark:text-green-300 bg-green-50 dark:bg-green-900/30 p-1 rounded">
                            {formatAuditValue(fc.after)}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  }

  // اگر فیلد object هست و deep diff داره
  if (diff && diff.type === 'object') {
    return (
      <div className="bg-white dark:bg-slate-800 rounded-lg p-4 border border-slate-200 dark:border-slate-700">
        <div className="text-sm font-bold text-slate-900 dark:text-slate-100 mb-3 flex items-center gap-2">
          <span className="bg-indigo-100 dark:bg-indigo-900 text-indigo-800 dark:text-indigo-200 px-2 py-0.5 rounded text-xs font-mono">
            {fieldName}
          </span>
          <span className="text-xs text-slate-500 dark:text-slate-400">(Object)</span>
        </div>

        {diff.fieldChanges && diff.fieldChanges.length > 0 && (
          <div className="space-y-2">
            {diff.fieldChanges.map((fc: any, idx: number) => (
              <div key={idx} className="bg-slate-50 dark:bg-slate-900 rounded p-2">
                <div className="text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">
                  {formatFieldName(fc.field)}:
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div className="text-xs text-red-700 dark:text-red-300 bg-red-50 dark:bg-red-900/20 p-1 rounded">
                    {formatAuditValue(fc.before)}
                  </div>
                  <div className="text-xs text-green-700 dark:text-green-300 bg-green-50 dark:bg-green-900/20 p-1 rounded">
                    {formatAuditValue(fc.after)}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // primitive ساده
  return (
    <div className="bg-white dark:bg-slate-800 rounded-lg p-3 border border-slate-200 dark:border-slate-700">
      <div className="text-sm font-bold text-slate-900 dark:text-slate-100 mb-3 flex items-center gap-2">
        <span className="bg-indigo-100 dark:bg-indigo-900 text-indigo-800 dark:text-indigo-200 px-2 py-0.5 rounded text-xs font-mono">
          {fieldName}
        </span>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <div>
          <div className="text-xs text-red-600 dark:text-red-400 font-semibold mb-1.5">❌ Before</div>
          <div className="text-sm text-slate-900 dark:text-slate-100 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">
            {formatAuditValue(before)}
          </div>
        </div>
        <div>
          <div className="text-xs text-green-600 dark:text-green-400 font-semibold mb-1.5">✅ After</div>
          <div className="text-sm text-slate-900 dark:text-slate-100 bg-green-50 dark:bg-green-900/20 p-2 rounded border border-green-200 dark:border-green-800">
            {formatAuditValue(after)}
          </div>
        </div>
      </div>
    </div>
  );
}

