// src/features/auth/ui/ForgotPasswordPage.tsx

import { useState } from 'react';
import { useAuth } from '../hooks/useAuth';
import { Mail, ArrowLeft, Loader2 } from 'lucide-react';

interface Props {
  onBack: () => void;
}

export function ForgotPasswordPage({ onBack }: Props) {
  const { requestPasswordReset, isLoading, error } = useAuth();
  const [email, setEmail] = useState('');
  const [sent, setSent] = useState(false);
  const [validationError, setValidationError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!email.trim()) {
      setValidationError('Email is required');
      return;
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setValidationError('Invalid email format');
      return;
    }

    try {
      await requestPasswordReset(email);
      setSent(true);
    } catch (err) {
      // Error handled by useAuth
    }
  };

  if (sent) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900 flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 shadow-2xl border border-white/20 text-center">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-green-500/20 text-green-400 text-3xl mb-4">
              ✓
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Check Your Email</h2>
            <p className="text-slate-300 mb-6">
              We've sent password reset instructions to <strong className="text-white">{email}</strong>
            </p>
            <button
              onClick={onBack}
              className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-all"
            >
              Back to Login
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-white mb-2">Forgot Password?</h1>
          <p className="text-slate-300">Enter your email to receive reset instructions</p>
        </div>

        <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 shadow-2xl border border-white/20">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-red-500/20 border border-red-500/50 rounded-lg p-3 text-sm text-red-200">
                {error}
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-slate-200 mb-2">
                Email Address
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => {
                    setEmail(e.target.value);
                    setValidationError('');
                  }}
                  className={`w-full pl-10 pr-4 py-3 bg-white/10 border rounded-lg text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all ${
                    validationError ? 'border-red-500' : 'border-white/20'
                  }`}
                  placeholder="Enter your email"
                  autoFocus
                />
              </div>
              {validationError && (
                <p className="mt-1 text-xs text-red-400">{validationError}</p>
              )}
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-600/50 text-white font-semibold rounded-lg transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-600/50"
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Sending...
                </>
              ) : (
                'Send Reset Instructions'
              )}
            </button>
          </form>

          <button
            onClick={onBack}
            className="w-full mt-4 py-3 text-slate-300 hover:text-white transition-colors flex items-center justify-center gap-2"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to Login
          </button>
        </div>
      </div>
    </div>
  );
}

// src/features/auth/ui/LoginPage.tsx

import { useState } from 'react';
import { useAuth } from '../hooks/useAuth';
import { Lock, User, Eye, EyeOff, Loader2 } from 'lucide-react';

interface Props {
  onForgotPassword?: () => void;
}

export function LoginPage({ onForgotPassword }: Props) {
  const { login, isLoading, error } = useAuth();
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    rememberMe: false,
  });
  const [showPassword, setShowPassword] = useState(false);
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});

  const validate = (): boolean => {
    const errors: Record<string, string> = {};

    if (!formData.username.trim()) {
      errors.username = 'Username is required';
    }

    if (!formData.password) {
      errors.password = 'Password is required';
    } else if (formData.password.length < 6) {
      errors.password = 'Password must be at least 6 characters';
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) return;

    try {
      await login(formData);
    } catch (err) {
      // Error handled by useAuth
    }
  };

  const handleChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (validationErrors[field]) {
      setValidationErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        {/* Logo & Title */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-blue-600 text-white text-2xl font-bold mb-4 shadow-lg shadow-blue-600/50">
            ICS
          </div>
          <h1 className="text-3xl font-bold text-white mb-2">Welcome Back</h1>
          <p className="text-slate-300">Sign in to your account to continue</p>
        </div>

        {/* Login Form */}
        <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 shadow-2xl border border-white/20">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-red-500/20 border border-red-500/50 rounded-lg p-3 text-sm text-red-200">
                {error}
              </div>
            )}

            {/* Username */}
            <div>
              <label className="block text-sm font-medium text-slate-200 mb-2">
                Username
              </label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input
                  type="text"
                  value={formData.username}
                  onChange={(e) => handleChange('username', e.target.value)}
                  className={`w-full pl-10 pr-4 py-3 bg-white/10 border rounded-lg text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all ${
                    validationErrors.username ? 'border-red-500' : 'border-white/20'
                  }`}
                  placeholder="Enter your username"
                  autoFocus
                />
              </div>
              {validationErrors.username && (
                <p className="mt-1 text-xs text-red-400">{validationErrors.username}</p>
              )}
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm font-medium text-slate-200 mb-2">
                Password
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={formData.password}
                  onChange={(e) => handleChange('password', e.target.value)}
                  className={`w-full pl-10 pr-12 py-3 bg-white/10 border rounded-lg text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all ${
                    validationErrors.password ? 'border-red-500' : 'border-white/20'
                  }`}
                  placeholder="Enter your password"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white transition-colors"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
              {validationErrors.password && (
                <p className="mt-1 text-xs text-red-400">{validationErrors.password}</p>
              )}
            </div>

            {/* Remember Me & Forgot Password */}
            <div className="flex items-center justify-between">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={formData.rememberMe}
                  onChange={(e) => handleChange('rememberMe', e.target.checked)}
                  className="w-4 h-4 rounded border-slate-600 bg-white/10 text-blue-600 focus:ring-blue-500"
                />
                <span className="text-sm text-slate-300">Remember me</span>
              </label>
              {onForgotPassword && (
                <button
                  type="button"
                  onClick={onForgotPassword}
                  className="text-sm text-blue-400 hover:text-blue-300 transition-colors"
                >
                  Forgot password?
                </button>
              )}
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-600/50 text-white font-semibold rounded-lg transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-600/50"
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Signing in...
                </>
              ) : (
                'Sign In'
              )}
            </button>
          </form>

          {/* Demo Credentials */}
          <div className="mt-6 pt-6 border-t border-white/20">
            <p className="text-xs text-slate-400 text-center mb-3">Demo Credentials</p>
            <div className="grid grid-cols-2 gap-2 text-xs">
              <button
                onClick={() => setFormData({ username: 'admin', password: 'admin123', rememberMe: false })}
                className="px-3 py-2 bg-white/5 hover:bg-white/10 rounded-lg text-slate-300 transition-colors"
              >
                Admin
              </button>
              <button
                onClick={() => setFormData({ username: 'sara.m', password: 'password', rememberMe: false })}
                className="px-3 py-2 bg-white/5 hover:bg-white/10 rounded-lg text-slate-300 transition-colors"
              >
                Manager
              </button>
            </div>
          </div>
        </div>

        {/* Footer */}
        <p className="text-center text-sm text-slate-400 mt-8">
          © 2024 ICS System. All rights reserved.
        </p>
      </div>
    </div>
  );
}

// src/features/client-management/ui/ClientDetails.tsx

import { useState, useRef, useMemo } from 'react';
import { Button, Badge, Card, Avatar } from '@design-system';
import { useTheme } from '@app/providers/ThemeProvider';
import { useClickOutside } from '@shared/hooks/useClickOutside';
import { usePermission } from '@shared/authorization/hooks/usePermission';
import type { Client, Contract, TariffLine } from '@entities/contract/types';
import { formatCurrency } from '@shared/lib/formatters';
import {
  calculateProgressFromTariffs,
  calculateInvoiceProgress,
  getProgressTextClass,
  getProgressBgClass,
  isExpiringSoon,
} from '@entities/contract/services/contractCalculations';

interface ClientDetailsProps {
  client: Client | null;
  contracts: Contract[];
  clientContracts: Contract[];
  filteredContracts: Contract[];
  contractTab: 'ALL' | 'CONTRACT' | 'WORK_ORDER';
  setContractTab: (tab: 'ALL' | 'CONTRACT' | 'WORK_ORDER') => void;
  contractTariffs: TariffLine[];
  onEdit: () => void;
  onClose: () => void;
  currentDepartment: string;
  onContractClick?: (contract: Contract) => void;
  canUpdate?: boolean;
  canDelete?: boolean;
  canRead?: boolean;
  onDelete?: () => void;
}

export function ClientDetails({
  client,
  contracts,
  clientContracts,
  filteredContracts,
  contractTab,
  setContractTab,
  contractTariffs,
  onEdit,
  onClose,
  currentDepartment,
  onContractClick,
  canUpdate = true,
  canDelete = true,
  canRead = true,
  onDelete,
}: ClientDetailsProps) {
  const { isDark } = useTheme();
  
  // 🔐 RBAC: چک کردن دسترسی به قراردادها و مالی
  const { can, canAny } = usePermission();
  const canViewContracts = canAny(['contract:read', 'contract:view_all', 'contract:view_own']);
  const canViewInvoices = canAny(['invoice:read', 'invoice:view_all', 'invoice:view_own']);

  const [showEmailDropdown, setShowEmailDropdown] = useState(false);
  const [showContactDropdown, setShowContactDropdown] = useState(false);
  const [toastMessage, setToastMessage] = useState('');

  const emailDropdownRef = useRef<HTMLDivElement>(null);
  const contactDropdownRef = useRef<HTMLDivElement>(null);

  useClickOutside(emailDropdownRef, () => setShowEmailDropdown(false));
  useClickOutside(contactDropdownRef, () => setShowContactDropdown(false));

  const filteredContactPersons = useMemo(() => {
    if (!client || !client.contactPersons) return [];
    return client.contactPersons.filter((cp: any) => cp.department === currentDepartment);
  }, [client, currentDepartment]);

  // Empty state
  if (!client) {
    return (
      <div className={`flex-1 flex items-center justify-center relative overflow-hidden min-h-[600px] ${
        isDark
          ? 'bg-gradient-to-br from-slate-800 via-slate-900 to-indigo-950/30'
          : 'bg-gradient-to-br from-slate-50 via-white to-indigo-50/30'}`}>
        <div className="absolute inset-0 opacity-[0.03]" style={{
          backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='${isDark ? '%23ffffff' : '%23000000'}' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`
        }} />

        <div className="text-center z-10 relative">
          <div className="relative inline-block mb-8">
            <div className="absolute inset-0 rounded-full bg-gradient-to-br from-indigo-400 to-violet-500 blur-2xl opacity-40 animate-pulse"/>
            <div className={`relative inline-flex items-center justify-center w-44 h-44 rounded-full shadow-2xl shadow-indigo-500/30 border-4 ${
              isDark ? 'bg-slate-800 border-slate-700' : 'bg-white border-white'}`}>
              <img src="/images/logo.png" alt="ICS Logo" className="w-36 h-36 object-contain"/>
            </div>
          </div>

          <h2 className={`text-3xl font-bold mb-3 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
            OFFSHORE & ENERGY DEPARTMENT INSPECTION PLATFORM
          </h2>
          <p className={`text-base max-w-md mx-auto leading-relaxed ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>
            Select a client from the list to view details, contracts, and contact information
          </p>

          <div className="flex items-center justify-center gap-6 mt-8">
            <div className="flex flex-col items-center gap-2">
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl ${isDark ? 'bg-indigo-900/50' : 'bg-indigo-100'}`}>👥</div>
              <span className={`text-xs font-medium ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Clients</span>
            </div>
            <div className="flex flex-col items-center gap-2">
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl ${isDark ? 'bg-emerald-900/50' : 'bg-emerald-100'}`}>📄</div>
              <span className={`text-xs font-medium ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Contracts</span>
            </div>
            <div className="flex flex-col items-center gap-2">
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl ${isDark ? 'bg-amber-900/50' : 'bg-amber-100'}`}>📧</div>
              <span className={`text-xs font-medium ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Contacts</span>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Computed values
  const totalValue = clientContracts.reduce((sum, c) => sum + c.total_value, 0);
  
  const totalInvoiced = (() => {
    const contractIds = clientContracts.map(c => c.id);
    return contractTariffs
      .filter(t => contractIds.includes(t.contract_id || ''))
      .reduce((sum, t) => sum + (t.invoiced || 0), 0);
  })();

  const totalUninvoicedWork = (() => {
    const contractIds = clientContracts.map(c => c.id);
    const tariffs = contractTariffs.filter(t => contractIds.includes(t.contract_id || ''));
    const performedWork = tariffs.reduce((sum, t) => {
      const rate = typeof t.rate === 'string' ? Number(t.rate.replace(/,/g, '')) || 0 : (t.rate || 0);
      const consumed = t.consumed_quantity || 0;
      return sum + (rate * consumed);
    }, 0);
    return Math.max(0, performedWork - totalInvoiced);
  })();

  const summaryTitle = contractTab === 'ALL' ? 'Total Agreements' : contractTab === 'CONTRACT' ? 'Total Contracts' : 'Total Work Orders';
  const dynamicContractCount = filteredContracts.length;

  const handleCopyEmail = async (email: string) => {
    let success = false;
    if (navigator.clipboard && window.isSecureContext) {
      try {
        await navigator.clipboard.writeText(email);
        success = true;
      } catch (err) {
        console.log('Clipboard API failed, trying fallback');
      }
    }
    if (!success) {
      try {
        const textArea = document.createElement('textarea');
        textArea.value = email;
        textArea.style.position = 'fixed';
        textArea.style.left = '-999999px';
        textArea.style.top = '-999999px';
        textArea.style.opacity = '0';
        textArea.setAttribute('readonly', '');
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        textArea.setSelectionRange(0, email.length);
        success = document.execCommand('copy');
        document.body.removeChild(textArea);
      } catch (err) {
        console.error('Fallback copy failed:', err);
      }
    }
    if (success) {
      setToastMessage('✅ Email address copied!');
    } else {
      setToastMessage('❌ Failed to copy email');
    }
    setTimeout(() => setToastMessage(''), 2500);
  };

  const handleContractClick = (contract: Contract) => {
    if (!canRead) {
      return;
    }
    onContractClick?.(contract);
  };

  return (
    <div className={`col-span-1 lg:col-span-8 flex flex-col rounded-xl panel-3d overflow-hidden transition-all duration-300 ease-in-out ${
      isDark ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200/70'}`}>
      {/* Header */}
      <div className={`border-b px-6 py-4 ${
        isDark ? 'border-slate-700 bg-gradient-to-r from-slate-800 to-slate-900' : 'border-slate-100 bg-gradient-to-r from-slate-50 to-white'}`}>
        <div className="flex items-center justify-between mb-4">
          <h2 className={`text-xs font-semibold uppercase tracking-wider ${isDark ? 'text-slate-200' : 'text-slate-600'}`}>Client Details</h2>
          <Button
            variant="ghost" size="sm" onClick={onClose}
            className={`transition-colors ${
              isDark ? 'text-slate-200 hover:text-rose-400 hover:bg-rose-600/30' : 'text-slate-400 hover:text-rose-600 hover:bg-rose-50'}`}
          >✕ Close Panel</Button>
        </div>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            {/* 🔧 FIX: Avatar با border و sizing بهتر */}
            <div className={`w-16 h-16 rounded-xl overflow-hidden border-2 ${
              isDark ? 'border-slate-600 bg-slate-800' : 'border-slate-200 bg-slate-50'
            } flex items-center justify-center`}>
              <Avatar name={client.name_en} gradient={client.logoColor} size="lg"/>
            </div>
            <div className="min-w-0 flex-1">
              <h3 className={`text-xl font-bold truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{client.name_en}</h3>
              <p className={`text-sm truncate ${isDark ? 'text-slate-300' : 'text-slate-600'}`} dir="rtl">{client.name_fa}</p>
            </div>
          </div>
          <div className="flex gap-2">
            {canUpdate && (
              <Button variant="outline" size="md" onClick={onEdit} className="gap-2 shadow-sm">
                <span>✏️</span> Edit Client
              </Button>
            )}
            {canDelete && onDelete && (
              <Button 
                variant="danger" 
                size="md" 
                onClick={onDelete} 
                className="gap-2 shadow-sm bg-rose-600 hover:bg-rose-700 text-white"
              >
                <span>🗑️</span> Delete
              </Button>
            )}
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-6">
        <div className="space-y-6">
          {/* Company/Personal Information */}
          {client.type === 'LEGAL' ? (
            <div className={`rounded-lg border p-4 ${
              isDark ? 'border-slate-600 bg-slate-800/30' : 'border-slate-200 bg-slate-50/30'}`}>
              <h3 className={`text-sm font-semibold mb-3 flex items-center gap-2 ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>🏢 Company Information</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4 text-sm">
                <div>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>National ID</div>
                  <div className={`font-mono text-xs truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{client.national_id || '—'}</div>
                </div>
                <div>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Registration No</div>
                  <div className={`font-mono text-xs truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{(client as any).registration_no || '—'}</div>
                </div>
                <div>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Economic Code</div>
                  <div className={`font-mono text-xs truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{(client as any).economic_code || '—'}</div>
                </div>
                <div>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Abbreviated Name</div>
                  <div className={`text-xs truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{(client as any).abbreviated_name || '—'}</div>
                </div>

                {/* Emails */}
                <div className="relative" ref={emailDropdownRef}>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Emails</div>
                  {(() => {
                    const contactEmails = filteredContactPersons.map((cp: any) => cp.email).filter((email: string) => email);
                    const allEmails = [
                      ...(client.email ? [client.email] : []),
                      ...((client as any).emails || []),
                      ...contactEmails
                    ].filter((email, index, self) => self.indexOf(email) === index);

                    if (allEmails.length > 0) {
                      return (
                        <button
                          onClick={() => setShowEmailDropdown(!showEmailDropdown)}
                          className="flex items-center gap-1.5 text-xs text-indigo-400 hover:text-indigo-700 font-medium">
                          <span>📧 {allEmails.length} email{allEmails.length > 1 ? 's' : ''}</span>
                          <span className={`text-[10px] transition-transform ${showEmailDropdown ? 'rotate-180' : ''}`}>▼</span>
                        </button>
                      );
                    }
                    return <div className={`text-xs ${isDark ? 'text-slate-300' : 'text-slate-400'}`}>—</div>;
                  })()}

                  {showEmailDropdown && (() => {
                    const contactEmails = filteredContactPersons.filter((cp: any) => cp.email).map((cp: any) => ({ email: cp.email, name: cp.name }));
                    const primaryEmail = client.email;
                    const otherEmails = (client as any).emails || [];

                    return (
                      <div className={`absolute top-full left-0 mt-1 w-72 border rounded-lg shadow-lg z-50 py-2 max-h-80 overflow-y-auto ${
                        isDark ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200'}`}>
                        {primaryEmail && (
                          <>
                            <div className={`px-3 py-1.5 text-[10px] uppercase font-semibold border-b ${
                              isDark ? 'text-slate-400 border-slate-700' : 'text-slate-500 border-slate-100'}`}>⭐ Primary Email</div>
                            <button
                              onClick={(e) => { e.stopPropagation(); handleCopyEmail(primaryEmail); setShowEmailDropdown(false); }}
                              className={`w-full text-left px-3 py-2 text-xs font-mono transition-colors flex items-center gap-2 border-b ${
                                isDark ? 'text-slate-200 hover:bg-indigo-900/30 hover:text-indigo-300 border-slate-700' : 'text-slate-700 hover:bg-indigo-50 hover:text-indigo-700 border-slate-100'}`}
                            >
                              <span className="truncate">{primaryEmail}</span>
                              <span className={`ml-auto ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>📋</span>
                            </button>
                          </>
                        )}
                        {otherEmails.length > 0 && (
                          <>
                            <div className={`px-3 py-1.5 text-[10px] uppercase font-semibold border-b ${
                              isDark ? 'text-slate-400 border-slate-700' : 'text-slate-500 border-slate-100'}`}>Other Emails</div>
                            {otherEmails.map((email: string, index: number) => (
                              <button
                                key={index}
                                onClick={(e) => { e.stopPropagation(); handleCopyEmail(email); setShowEmailDropdown(false); }}
                                className={`w-full text-left px-3 py-2 text-xs font-mono transition-colors flex items-center gap-2 border-b ${
                                  isDark ? 'text-slate-200 hover:bg-indigo-900/30 hover:text-indigo-300 border-slate-700' : 'text-slate-700 hover:bg-indigo-50 hover:text-indigo-700 border-slate-50'}`}
                              >
                                <span className={`text-slate-400`}>📋</span>
                                <span className="truncate">{email}</span>
                              </button>
                            ))}
                          </>
                        )}
                        {contactEmails.length > 0 && (
                          <>
                            <div className={`px-3 py-1.5 text-[10px] uppercase font-semibold border-b ${
                              isDark ? 'text-slate-400 border-slate-700' : 'text-slate-500 border-slate-100'}`}>👥 Contact Persons</div>
                            {contactEmails.map((contact: any, index: number) => (
                              <button
                                key={index}
                                onClick={(e) => { e.stopPropagation(); handleCopyEmail(contact.email); setShowEmailDropdown(false); }}
                                className={`w-full text-left px-3 py-2 transition-colors border-b last:border-0 ${
                                  isDark ? 'hover:bg-indigo-900/30 border-slate-700' : 'hover:bg-indigo-50 border-slate-50'}`}
                              >
                                <div className="flex items-center justify-between mb-0.5">
                                  <span className={`text-xs font-semibold truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{contact.name}</span>
                                  <span className={`text-slate-400`}>📋</span>
                                </div>
                                <div className="text-[10px] font-mono text-indigo-600 truncate">{contact.email}</div>
                              </button>
                            ))}
                          </>
                        )}
                      </div>
                    );
                  })()}
                </div>

                {/* Contact Persons */}
                <div className="relative" ref={contactDropdownRef}>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Contact Persons</div>
                  {filteredContactPersons.length > 0 ? (
                    <button
                      onClick={() => setShowContactDropdown(!showContactDropdown)}
                      className="flex items-center gap-1.5 text-xs text-indigo-400 hover:text-indigo-700 font-medium">
                      <span>👥 {filteredContactPersons.length} contact{filteredContactPersons.length > 1 ? 's' : ''}</span>
                      <span className={`text-[10px] transition-transform ${showContactDropdown ? 'rotate-180' : ''}`}>▼</span>
                    </button>
                  ) : (
                    <div className={`text-xs ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>—</div>
                  )}

                  {showContactDropdown && filteredContactPersons.length > 0 && (
                    <div className={`absolute top-full right-0 mt-1 w-72 bg-card border border-theme rounded-lg shadow-lg z-50 py-2 max-h-80 overflow-y-auto ${
                      isDark ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200'}`}>
                      {filteredContactPersons.map((cp: any) => (
                        <div key={cp.id} className={`px-3 py-2 border-b last:border-0 transition-colors ${
                          isDark ? 'border-slate-700 hover:bg-slate-700/50' : 'border-slate-50 hover:bg-slate-50'}`}>
                          <div className="flex items-center justify-between mb-1">
                            <span className={`text-xs font-semibold ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{cp.name}</span>
                          </div>
                          {cp.position && <div className={`text-[10px] mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>{cp.position}</div>}
                          <div className="flex items-center gap-2 text-[10px]">
                            <span className={`text-slate-400`}>📞</span>
                            <span className={`font-mono ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>{cp.mobile}</span>
                          </div>
                          {cp.email && (
                            <button
                              onClick={(e) => { e.stopPropagation(); handleCopyEmail(cp.email); }}
                              className="flex items-center gap-2 text-[10px] mt-0.5 hover:text-indigo-600 transition-colors">
                              <span className={`text-slate-400`}>✉️</span>
                              <span className="font-mono text-indigo-600 truncate">{cp.email}</span>
                              <span className={`text-slate-400 ml-auto`}>📋</span>
                            </button>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className={`rounded-lg border p-4 ${
              isDark ? 'border-slate-600 bg-slate-800/30' : 'border-slate-200 bg-slate-50/30'}`}>
              <h3 className={`text-sm font-semibold mb-3 flex items-center gap-2 ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>👤 Personal Information</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4 text-sm">
                <div>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>National Code</div>
                  <div className={`font-mono text-xs truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{client.national_id || '—'}</div>
                </div>
                <div>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Mobile</div>
                  <div className={`text-xs truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{client.phone || '—'}</div>
                </div>

                {/* Emails */}
                <div className="relative" ref={emailDropdownRef}>
                  <div className={`text-[10px] uppercase font-semibold mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>Emails</div>
                  {(() => {
                    const allEmails = [
                      ...(client.email ? [client.email] : []),
                      ...((client as any).emails || [])
                    ].filter((email, index, self) => self.indexOf(email) === index);

                    if (allEmails.length > 0) {
                      return (
                        <button onClick={() => setShowEmailDropdown(!showEmailDropdown)} className="flex items-center gap-1.5 text-xs text-indigo-400 hover:text-indigo-700 font-medium">
                          <span>📧 {allEmails.length} email{allEmails.length > 1 ? 's' : ''}</span>
                          <span className={`text-[10px] transition-transform ${showEmailDropdown ? 'rotate-180' : ''}`}>▼</span>
                        </button>
                      );
                    }
                    return <div className={`text-xs ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>—</div>;
                  })()}

                  {showEmailDropdown && (() => {
                    const allEmails = [
                      ...(client.email ? [client.email] : []),
                      ...((client as any).emails || [])
                    ].filter((email, index, self) => self.indexOf(email) === index);

                    return (
                      <div className={`absolute top-full left-0 mt-1 w-80 bg-card border border-theme rounded-lg shadow-lg z-50 py-2 max-h-80 overflow-y-auto ${
                        isDark ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200'}`}>
                        {client.email && (
                          <>
                            <div className={`px-3 py-1.5 text-[10px] uppercase font-semibold border-b ${
                              isDark ? 'text-slate-400 border-slate-700' : 'text-slate-500 border-slate-100'}`}>⭐ Primary Email</div>
                            <button onClick={() => { handleCopyEmail(client.email!); setShowEmailDropdown(false); }} className={`w-full text-left px-3 py-2 text-xs font-mono transition-colors flex items-center gap-2 border-b ${
                              isDark ? 'text-slate-200 hover:bg-indigo-900/30 hover:text-indigo-300 border-slate-700' : 'text-slate-700 hover:bg-indigo-50 hover:text-indigo-700 border-slate-100'}`}>
                              
                              <span className="truncate">{client.email}</span>
                            </button>
                          </>
                        )}
                        {(client as any).emails && (client as any).emails.length > 0 && (
                          <>
                            <div className={`px-3 py-1.5 text-[10px] uppercase font-semibold border-b ${
                              isDark ? 'text-slate-400 border-slate-700' : 'text-slate-500 border-slate-100'}`}>Other Emails</div>
                            {(client as any).emails.map((email: string, index: number) => (
                              <button key={index} onClick={() => { handleCopyEmail(email); setShowEmailDropdown(false); }} className={`w-full text-left px-3 py-2 text-xs font-mono transition-colors flex items-center gap-2 ${
                                isDark ? 'text-slate-200 hover:bg-indigo-900/30 hover:text-indigo-300' : 'text-slate-700 hover:bg-indigo-50 hover:text-indigo-700'}`}>
                                <span className={`text-slate-400`}>📋</span>
                                <span className="truncate">{email}</span>
                              </button>
                            ))}
                          </>
                        )}
                      </div>
                    );
                  })()}
                </div>
              </div>
            </div>
          )}

          {/* 🔐 RBAC: Stats Cards - فقط با permission مربوطه */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-2 lg:gap-4">
            {/* Total Agreements - فقط با contract:read */}
            {canViewContracts && (
              <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-600 bg-slate-800/30' : 'border-slate-200'}`}>
                <div className={`text-xs mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>{summaryTitle}</div>
                {/* 🔧 FIX: truncate برای اعداد طولانی */}
                <div className={`text-2xl font-bold truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{dynamicContractCount}</div>
              </div>
            )}

            {/* Total Value - فقط با contract:read */}
            {canViewContracts && (
              <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-600 bg-slate-800/30' : 'border-slate-200'}`}>
                <div className={`text-xs mb-1 ${isDark ? 'text-slate-200' : 'text-slate-600'}`}>Total Value of Agreements</div>
                {/* 🔧 FIX: truncate برای اعداد طولانی */}
                <div className="text-xl font-bold text-accent-emerald truncate" title={formatCurrency(totalValue)}>
                  {formatCurrency(totalValue)}
                </div>
              </div>
            )}

            {/* Invoiced - فقط با invoice:read */}
            {canViewInvoices && (
              <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-600 bg-slate-800/30' : 'border-slate-200'}`}>
                <div className={`text-xs mb-1 ${isDark ? 'text-slate-200' : 'text-slate-600'}`}>Invoiced Works</div>
                {/* 🔧 FIX: truncate برای اعداد طولانی */}
                <div className="text-xl font-bold text-accent-indigo truncate" title={formatCurrency(totalInvoiced)}>
                  {formatCurrency(totalInvoiced)}
                </div>
              </div>
            )}

            {/* Not Invoiced - فقط با invoice:read */}
            {canViewInvoices && (
              <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-600 bg-slate-800/30' : 'border-slate-200'}`}>
                <div className={`text-xs mb-1 ${isDark ? 'text-slate-200' : 'text-slate-600'}`}>Not Invoiced Works</div>
                {/* 🔧 FIX: truncate برای اعداد طولانی */}
                <div className={`text-xl font-bold truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`} title={formatCurrency(totalUninvoicedWork)}>
                  {formatCurrency(totalUninvoicedWork)}
                </div>
              </div>
            )}
          </div>

          {/* 🔐 RBAC: Agreements Section - فقط با contract:read */}
          {canViewContracts && (
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className={`text-sm font-semibold ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>Agreements</h3>
                <div className={`flex gap-1 rounded-lg border p-0.5 text-xs ${
                  isDark ? 'border-slate-600 bg-slate-800' : 'border-slate-200 bg-slate-50'}`}>
                  {(['ALL', 'CONTRACT', 'WORK_ORDER'] as const).map((t) => (
                    <button
                      key={t}
                      onClick={() => setContractTab(t)}
                      className={`rounded-md px-3 py-1.5 font-medium transition-colors ${
                        contractTab === t
                          ? (isDark ? 'bg-slate-700 text-slate-100 shadow-sm' : 'bg-white text-slate-900 shadow-sm')
                          : (isDark ? 'text-slate-300' : 'text-slate-600')
                      }`}
                    >
                      {t === 'ALL' ? `All (${clientContracts.length})` : t === 'CONTRACT' ? `📄 Contracts (${clientContracts.filter(c => c.type === 'CONTRACT').length})` : `📦 Work Orders (${clientContracts.filter(c => c.type === 'WORK_ORDER').length})`}
                    </button>
                  ))}
                </div>
              </div>
              <div className="space-y-3">
                {filteredContracts.map((contract) => {
                  const workProgress = calculateProgressFromTariffs(contract);
                  const invoiceProgress = calculateInvoiceProgress(contract);
                  const expiringInfo = isExpiringSoon(contract);

                  return (
                    <div
                      key={contract.id}
                      onClick={() => handleContractClick(contract)}
                      className={`rounded-lg border p-4 transition-colors ${
                        canRead ? 'cursor-pointer' : 'cursor-not-allowed opacity-70'
                      } ${
                        isDark ? 'border-slate-700 hover:border-indigo-500' : 'border-slate-200 hover:border-indigo-300'
                      } ${expiringInfo.expiring ? (isDark ? 'border-amber-700/50 bg-amber-950/10' : 'border-amber-300 bg-amber-50/30') : ''}`}
                    >
                      <div className="flex items-start justify-between mb-3">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1 flex-wrap">
                            <Badge tone={contract.type === 'CONTRACT' ? 'indigo' : 'amber'}>
                              {contract.type === 'CONTRACT' ? '📄 Contract' : '📦 Work Order'}
                            </Badge>
                            <span className={`font-mono text-xs truncate ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>
                              {contract.contract_no}
                            </span>
                            <Badge tone="slate">
                              {contract.tariffs} {contract.tariffs === 1 ? 'Tariff' : 'Tariffs'}
                            </Badge>
                            {expiringInfo.expiring && (
                              <Badge tone="danger" className="gap-1 animate-pulse">
                                <span>⚠️</span>
                                <span>Expiring Soon</span>
                              </Badge>
                            )}
                          </div>
                          {/* 🔧 FIX: truncate برای عنوان طولانی */}
                          <h4 className={`text-sm font-semibold truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`} title={contract.contract_title}>
                            {contract.contract_title}
                          </h4>
                        </div>
                        <div className="text-right ml-4 shrink-0">
                          {/* 🔧 FIX: truncate برای اعداد طولانی */}
                          <div className={`text-sm font-bold truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`} title={formatCurrency(contract.total_value, contract.currency)}>
                            {formatCurrency(contract.total_value, contract.currency)}
                          </div>
                          <Badge tone={contract.status === 'ACTIVE' ? 'emerald' : 'slate'}>
                            {contract.status === 'ACTIVE' ? '🟢 Active' : contract.status}
                          </Badge>
                        </div>
                      </div>

                      <div className={`flex items-center justify-between text-[10px] mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>
                        <span>Work Performed</span>
                        <span className={`font-semibold ${getProgressTextClass(workProgress)}`}>{workProgress.toFixed(1)}%</span>
                      </div>
                      <div className={`h-1.5 rounded-full overflow-hidden ${isDark ? 'bg-slate-700' : 'bg-slate-100'}`}>
                        <div className={`h-full rounded-full ${getProgressBgClass(workProgress)}`} style={{ width: `${Math.min(workProgress, 100)}%` }} />
                      </div>

                      <div className={`flex items-center justify-between text-[10px] mt-3 mb-1 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>
                        <span>Invoiced</span>
                        <span className={`font-semibold ${getProgressTextClass(invoiceProgress)}`}>{invoiceProgress.toFixed(1)}%</span>
                      </div>
                      <div className={`h-1.5 rounded-full overflow-hidden ${isDark ? 'bg-slate-700' : 'bg-slate-100'}`}>
                        <div className={`h-full rounded-full ${getProgressBgClass(invoiceProgress)}`} style={{ width: `${Math.min(invoiceProgress, 100)}%` }} />
                      </div>

                      <div className={`flex items-center justify-between text-xs mt-2 ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>
                        <span>{contract.start_date} → {contract.end_date}</span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 bg-emerald-600 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 animate-in slide-in-from-bottom-4">
          <span className="text-sm font-medium">{toastMessage}</span>
        </div>
      )}
    </div>
  );
}

// src/features/client-management/ui/ClientForm.tsx

import { useState, useEffect } from 'react';
import { Button, Badge, Modal } from '@design-system';
import { useTheme } from '@app/providers/ThemeProvider';
import type { Client } from '@entities/contract/types';
import { validateNationalCode, validateNationalId, validateMobile } from '@shared/lib/validators';

// 🔐 RBAC Imports
import { usePermission } from '@shared/authorization/hooks/usePermission';
import { showToast } from '@shared/ui/ToastContainer';

interface ClientFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: any) => void;
  clients: Client[];
  currentDepartment: string;
  onDuplicateWarning?: React.Dispatch<
    React.SetStateAction<{
      field: string;
      client: any;
      message: string;
    } | null>
  >;
}

export function ClientForm({
  isOpen,
  onClose,
  onSave,
  clients,
  currentDepartment,
}: ClientFormProps) {
  const { isDark } = useTheme();
  
  // 🔐 RBAC: چک کردن permission
  const { can } = usePermission();
  const canCreate = can('client:create');

  const [addForm, setAddForm] = useState({
    name_en: '',
    name_fa: '',
    abbreviated_name: '',
    company_type: 'Private Joint Stock',
    national_id: '',
    economic_code: '',
    registration_no: '',
    address_en: '',
    address_fa: '',
    primary_phone: '',
    email_inbox: '',
    category: 'OIL_GAS' as const,
    contactPersons: [
      { id: '1', name: '', position: '', mobile: '', email: '' },
    ],
  });

  const [addErrors, setAddErrors] = useState<any>({});
  const [duplicateWarning, setDuplicateWarning] = useState<{
    field: string;
    client: any;
    message: string;
  } | null>(null);

  // 🔐 RBAC: اگر دسترسی نداره، مودال رو نبند و پیام بده
  useEffect(() => {
    if (isOpen && !canCreate) {
      showToast('error', 'Access Denied', 'You do not have permission to create clients');
      onClose();
    }
  }, [isOpen, canCreate, onClose]);

  // Reset form when modal opens
  useEffect(() => {
    if (isOpen && canCreate) {
      setAddForm({
        name_en: '',
        name_fa: '',
        abbreviated_name: '',
        company_type: 'Private Joint Stock',
        national_id: '',
        economic_code: '',
        registration_no: '',
        address_en: '',
        address_fa: '',
        primary_phone: '',
        email_inbox: '',
        category: 'OIL_GAS',
        contactPersons: [
          { id: '1', name: '', position: '', mobile: '', email: '' },
        ],
      });
      setAddErrors({});
      setDuplicateWarning(null);
    }
  }, [isOpen, canCreate]);

  // Check for duplicates
  useEffect(() => {
    if (!isOpen) return;

    const timer = setTimeout(() => {
      let found: any = null;
      let field = '';
      const normalize = (str: string) => str.toLowerCase().replace(/\s+/g, '').trim();

      if (addForm.name_en.trim().length >= 3) {
        found = clients.find((c) => normalize(c.name_en) === normalize(addForm.name_en));
        if (found) field = 'name_en';
      }

      if (!found && addForm.national_id && addForm.national_id.length >= 10) {
        found = clients.find((c) => c.national_id && c.national_id === addForm.national_id);
        if (found) field = 'national_id';
      }

      if (!found && addForm.company_type && addForm.registration_no.trim()) {
        found = clients.find((c) => (c as any).registration_no === addForm.registration_no);
        if (found) field = 'registration_no';
      }

      if (found) {
        const dept = (found as any).departments?.[0] || 'Unknown';
        const totalContacts = (found as any).contactPersons?.length || 0;
        setDuplicateWarning({
          field,
          client: found,
          message: `⚠️ This client already exists in ${dept}. Total contacts: ${totalContacts}`,
        });
      } else {
        setDuplicateWarning(null);
      }
    }, 200);

    return () => clearTimeout(timer);
  }, [addForm.national_id, addForm.name_en, addForm.registration_no, clients, addForm.company_type, isOpen]);

  const validateAddForm = () => {
    const errors: any = {};
    if (!addForm.name_en.trim()) errors.name_en = 'English name is required';
    if (!addForm.name_fa.trim()) errors.name_fa = 'نام فارسی الزامی است';
    if (!addForm.national_id) errors.national_id = 'National ID/Code is required';
    else if (addForm.company_type && !validateNationalId(addForm.national_id))
      errors.national_id = 'Must be exactly 11 digits';
    else if (!addForm.company_type && !validateNationalCode(addForm.national_id))
      errors.national_id = 'Invalid national code';

    if (addForm.company_type && !addForm.registration_no)
      errors.registration_no = 'Registration number is required';

    if (!addForm.primary_phone) errors.primary_phone = 'Primary phone is required';
    else if (!validateMobile(addForm.primary_phone))
      errors.primary_phone = 'Invalid mobile format';

    if (!addForm.address_en.trim()) errors.address_en = 'English address is required';
    if (!addForm.address_fa.trim()) errors.address_fa = 'آدرس فارسی الزامی است';

    const validContacts = addForm.contactPersons.filter(
      (cp) => cp.name.trim() && validateMobile(cp.mobile)
    );
    if (addForm.company_type && validContacts.length === 0)
      errors.contactPersons = 'At least one valid contact person required';

    setAddErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSave = () => {
    // 🔐 RBAC: چک کردن permission قبل از submit
    if (!canCreate) {
      showToast('error', 'Access Denied', 'You do not have permission to create clients');
      return;
    }

    if (!validateAddForm()) return;
    if (duplicateWarning) {
      showToast('warning', 'Duplicate Warning', 'Please resolve the duplicate client warning first.');
      return;
    }

    const newClient: any = {
      id: `c${Date.now()}`,
      type: addForm.company_type ? 'LEGAL' : 'INDIVIDUAL',
      name_en: addForm.name_en,
      name_fa: addForm.name_fa,
      national_id: addForm.national_id,
      category: addForm.category,
      contacts: addForm.company_type
        ? addForm.contactPersons.filter((cp) => cp.name.trim()).length
        : 0,
      contracts: 0,
      logoColor: 'from-indigo-500 to-violet-600',
      email: addForm.email_inbox,
      phone: addForm.primary_phone,
      address_en: addForm.address_en,
      address_fa: addForm.address_fa,
      departments: [currentDepartment],
      contactPersons: addForm.company_type
        ? addForm.contactPersons
            .filter((cp) => cp.name.trim())
            .map((cp) => ({ ...cp, department: currentDepartment }))
        : [],
    };

    if (addForm.company_type) {
      newClient.company_type = addForm.company_type;
      newClient.registration_no = addForm.registration_no;
      newClient.economic_code = addForm.economic_code;
      newClient.abbreviated_name = addForm.abbreviated_name;
    }

    onSave(newClient);
    onClose();
  };

  const addContactPerson = () =>
    setAddForm({
      ...addForm,
      contactPersons: [
        ...addForm.contactPersons,
        { id: Date.now().toString(), name: '', position: '', mobile: '', email: '' },
      ],
    });

  const removeContactPerson = (id: string) =>
    setAddForm({
      ...addForm,
      contactPersons: addForm.contactPersons.filter((cp) => cp.id !== id),
    });

  const updateContactPerson = (id: string, field: string, value: string) =>
    setAddForm({
      ...addForm,
      contactPersons: addForm.contactPersons.map((cp) =>
        cp.id === id ? { ...cp, [field]: value } : cp
      ),
    });

  return (
    <Modal
      isOpen={isOpen}
      onClose={() => {
        onClose();
        setDuplicateWarning(null);
      }}
      title="Entity Onboarding"
      size="xl"
    >
      <div className="space-y-6">
        {/* Type Selector */}
        <div
          className={`flex gap-2 p-1.5 rounded-xl border w-fit ${
            isDark ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'
          }`}
        >
          <button
            type="button"
            onClick={() => setAddForm({ ...addForm, company_type: 'Private Joint Stock' })}
            className={`px-6 py-2.5 rounded-lg text-sm font-semibold transition-all ${
              addForm.company_type
                ? 'bg-indigo-600 text-white shadow-md'
                : isDark
                ? 'text-slate-300 hover:bg-slate-700'
                : 'text-slate-600 hover:bg-white'
            }`}
          >
            🏢 LEGAL
          </button>
          <button
            type="button"
            onClick={() => setAddForm({ ...addForm, company_type: '' })}
            className={`px-6 py-2.5 rounded-lg text-sm font-semibold transition-all ${
              !addForm.company_type
                ? 'bg-indigo-600 text-white shadow-md'
                : isDark
                ? 'text-slate-300 hover:bg-slate-700'
                : 'text-slate-600 hover:bg-white'
            }`}
          >
            👤 INDIVIDUAL
          </button>
        </div>

        {/* Basic Identity */}
        <div
          className={`rounded-2xl border p-6 ${
            isDark ? 'border-slate-700' : 'border-slate-200'
          }`}
        >
          <h2
            className={`text-lg font-bold mb-6 flex items-center gap-2 ${
              isDark ? 'text-slate-100' : 'text-slate-900'
            }`}
          >
            🌐 BASIC IDENTITY
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            {/* Name EN */}
            <div>
              <label
                className={`mb-1.5 block text-xs font-semibold ${
                  isDark ? 'text-slate-300' : 'text-slate-700'
                }`}
              >
                Full Name (English) *
              </label>
              <input
                value={addForm.name_en}
                onChange={(e) => setAddForm({ ...addForm, name_en: e.target.value })}
                className={`w-full rounded-lg border py-2.5 px-3 text-sm focus:outline-none focus:ring-2 ${
                  addErrors.name_en
                    ? 'border-rose-300 focus:ring-rose-100'
                    : isDark
                    ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400 focus:ring-indigo-900'
                    : 'border-slate-200 bg-white focus:border-indigo-400 focus:ring-indigo-100'
                }`}
              />
              {duplicateWarning?.field === 'name_en' && (
                <div className="mt-2 rounded-lg border border-amber-200 bg-amber-50 p-3">
                  <p className="text-xs font-medium text-amber-900 mb-2">
                    {duplicateWarning.message}
                  </p>
                </div>
              )}
              {addErrors.name_en && !duplicateWarning && (
                <p className="mt-1 text-[11px] font-medium text-rose-600">
                  ✕ {addErrors.name_en}
                </p>
              )}
            </div>

            {/* Name FA */}
            <div dir="rtl">
              <label
                className={`mb-1.5 block text-xs font-semibold text-left ${
                  isDark ? 'text-slate-300' : 'text-slate-700'
                }`}
              >
                Full Name (Farsi) *
              </label>
              <input
                value={addForm.name_fa}
                onChange={(e) => setAddForm({ ...addForm, name_fa: e.target.value })}
                className={`w-full rounded-lg border py-2.5 px-3 text-sm text-right focus:outline-none focus:ring-2 ${
                  addErrors.name_fa
                    ? 'border-rose-300 focus:ring-rose-100'
                    : isDark
                    ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400 focus:ring-indigo-900'
                    : 'border-slate-200 bg-white focus:border-indigo-400 focus:ring-indigo-100'
                }`}
              />
              {addErrors.name_fa && (
                <p className="mt-1 text-[11px] font-medium text-rose-600 text-right">
                  ✕ {addErrors.name_fa}
                </p>
              )}
            </div>

            {/* Abbreviated Name */}
            {addForm.company_type && (
              <div>
                <label
                  className={`mb-1.5 block text-xs font-semibold ${
                    isDark ? 'text-slate-300' : 'text-slate-700'
                  }`}
                >
                  Abbreviated Name
                </label>
                <input
                  value={addForm.abbreviated_name}
                  onChange={(e) =>
                    setAddForm({ ...addForm, abbreviated_name: e.target.value })
                  }
                  className={`w-full rounded-lg border py-2.5 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-100 ${
                    isDark
                      ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400'
                      : 'border-slate-200 bg-white focus:border-indigo-400'
                  }`}
                />
              </div>
            )}

            {/* Company Type */}
            {addForm.company_type && (
              <div>
                <label
                  className={`mb-1.5 block text-xs font-semibold ${
                    isDark ? 'text-slate-300' : 'text-slate-700'
                  }`}
                >
                  Company Type *
                </label>
                <select
                  value={addForm.company_type}
                  onChange={(e) =>
                    setAddForm({ ...addForm, company_type: e.target.value })
                  }
                  className={`w-full rounded-lg border py-2.5 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-100 ${
                    isDark
                      ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400'
                      : 'border-slate-200 bg-white focus:border-indigo-400'
                  }`}
                >
                  <option value="Private Joint Stock">Private Joint Stock</option>
                  <option value="Public Joint Stock">Public Joint Stock</option>
                  <option value="Limited Liability">Limited Liability</option>
                </select>
              </div>
            )}

            {/* National ID */}
            <div>
              <label
                className={`mb-1.5 block text-xs font-semibold ${
                  isDark ? 'text-slate-300' : 'text-slate-700'
                }`}
              >
                {addForm.company_type
                  ? 'National ID (11 digits) *'
                  : 'National Code (10 digits) *'}
              </label>
              <input
                value={addForm.national_id}
                onChange={(e) =>
                  setAddForm({
                    ...addForm,
                    national_id: e.target.value.replace(/\D/g, ''),
                  })
                }
                maxLength={addForm.company_type ? 11 : 10}
                className={`w-full rounded-lg border py-2.5 px-3 text-sm font-mono focus:outline-none focus:ring-2 ${
                  addErrors.national_id
                    ? 'border-rose-300 focus:ring-rose-100'
                    : isDark
                    ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400 focus:ring-indigo-900'
                    : 'border-slate-200 bg-white focus:border-indigo-400 focus:ring-indigo-100'
                }`}
              />
              {duplicateWarning?.field === 'national_id' && (
                <div className="mt-2 rounded-lg border border-amber-200 bg-amber-50 p-3">
                  <p className="text-xs font-medium text-amber-900 mb-2">
                    {duplicateWarning.message}
                  </p>
                </div>
              )}
              {addErrors.national_id && !duplicateWarning && (
                <p className="mt-1 text-[11px] font-medium text-rose-600">
                  ✕ {addErrors.national_id}
                </p>
              )}
            </div>

            {/* Economic Code */}
            {addForm.company_type && (
              <div>
                <label
                  className={`mb-1.5 block text-xs font-semibold ${
                    isDark ? 'text-slate-300' : 'text-slate-700'
                  }`}
                >
                  Economic Code
                </label>
                <input
                  value={addForm.economic_code}
                  onChange={(e) =>
                    setAddForm({
                      ...addForm,
                      economic_code: e.target.value.replace(/\D/g, ''),
                    })
                  }
                  className={`w-full rounded-lg border py-2.5 px-3 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-indigo-100 ${
                    isDark
                      ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400'
                      : 'border-slate-200 bg-white focus:border-indigo-400'
                  }`}
                />
              </div>
            )}

            {/* Registration No */}
            {addForm.company_type && (
              <div>
                <label
                  className={`mb-1.5 block text-xs font-semibold ${
                    isDark ? 'text-slate-300' : 'text-slate-700'
                  }`}
                >
                  Registration Number *
                </label>
                <input
                  value={addForm.registration_no}
                  onChange={(e) =>
                    setAddForm({ ...addForm, registration_no: e.target.value })
                  }
                  className={`w-full rounded-lg border py-2.5 px-3 text-sm focus:outline-none focus:ring-2 ${
                    addErrors.registration_no
                      ? 'border-rose-300 focus:ring-rose-100'
                      : isDark
                      ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400 focus:ring-indigo-900'
                      : 'border-slate-200 bg-white focus:border-indigo-400 focus:ring-indigo-100'
                  }`}
                />
                {duplicateWarning?.field === 'registration_no' && (
                  <div className="mt-2 rounded-lg border border-amber-200 bg-amber-50 p-3">
                    <p className="text-xs font-medium text-amber-900 mb-2">
                      {duplicateWarning.message}
                    </p>
                  </div>
                )}
                {addErrors.registration_no && !duplicateWarning && (
                  <p className="mt-1 text-[11px] font-medium text-rose-600">
                    ✕ {addErrors.registration_no}
                  </p>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Contact Hub */}
        <div
          className={`rounded-2xl border p-6 ${
            isDark ? 'border-slate-700' : 'border-slate-200'
          }`}
        >
          <h2
            className={`text-lg font-bold mb-6 flex items-center gap-2 ${
              isDark ? 'text-slate-100' : 'text-slate-900'
            }`}
          >
            📞 CONTACT HUB
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <div>
              <label
                className={`mb-1.5 block text-xs font-semibold ${
                  isDark ? 'text-slate-300' : 'text-slate-700'
                }`}
              >
                Primary Phone *
              </label>
              <input
                value={addForm.primary_phone}
                onChange={(e) =>
                  setAddForm({
                    ...addForm,
                    primary_phone: e.target.value.replace(/\D/g, ''),
                  })
                }
                maxLength={11}
                className={`w-full rounded-lg border py-2.5 px-3 text-sm font-mono focus:outline-none focus:ring-2 ${
                  addErrors.primary_phone
                    ? 'border-rose-300 focus:ring-rose-100'
                    : isDark
                    ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400 focus:ring-indigo-900'
                    : 'border-slate-200 bg-white focus:border-indigo-400 focus:ring-indigo-100'
                }`}
              />
              {addErrors.primary_phone && (
                <p className="mt-1 text-[11px] font-medium text-rose-600">
                  ✕ {addErrors.primary_phone}
                </p>
              )}
            </div>
            <div>
              <label
                className={`mb-1.5 block text-xs font-semibold ${
                  isDark ? 'text-slate-300' : 'text-slate-700'
                }`}
              >
                Email Inbox
              </label>
              <input
                type="email"
                value={addForm.email_inbox}
                onChange={(e) =>
                  setAddForm({ ...addForm, email_inbox: e.target.value })
                }
                className={`w-full rounded-lg border py-2.5 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-100 ${
                  isDark
                    ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400'
                    : 'border-slate-200 bg-white focus:border-indigo-400'
                }`}
              />
            </div>
          </div>
        </div>

        {/* Official Address */}
        <div
          className={`rounded-2xl border p-6 ${
            isDark ? 'border-slate-700' : 'border-slate-200'
          }`}
        >
          <h2
            className={`text-lg font-bold mb-6 flex items-center gap-2 ${
              isDark ? 'text-slate-100' : 'text-slate-900'
            }`}
          >
            🏠 OFFICIAL ADDRESS
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <div>
              <label
                className={`mb-1.5 block text-xs font-semibold ${
                  isDark ? 'text-slate-300' : 'text-slate-700'
                }`}
              >
                Address (English) *
              </label>
              <textarea
                value={addForm.address_en}
                onChange={(e) =>
                  setAddForm({ ...addForm, address_en: e.target.value })
                }
                rows={3}
                className={`w-full rounded-lg border py-2.5 px-3 text-sm focus:outline-none focus:ring-2 ${
                  addErrors.address_en
                    ? 'border-rose-300 focus:ring-rose-100'
                    : isDark
                    ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400 focus:ring-indigo-900'
                    : 'border-slate-200 bg-white focus:border-indigo-400 focus:ring-indigo-100'
                }`}
              />
              {addErrors.address_en && (
                <p className="mt-1 text-[11px] font-medium text-rose-600">
                  ✕ {addErrors.address_en}
                </p>
              )}
            </div>
            <div dir="rtl">
              <label
                className={`mb-1.5 block text-xs font-semibold text-left ${
                  isDark ? 'text-slate-300' : 'text-slate-700'
                }`}
              >
                Address (Farsi) *
              </label>
              <textarea
                value={addForm.address_fa}
                onChange={(e) =>
                  setAddForm({ ...addForm, address_fa: e.target.value })
                }
                rows={3}
                className={`w-full rounded-lg border py-2.5 px-3 text-sm text-right focus:outline-none focus:ring-2 ${
                  addErrors.address_fa
                    ? 'border-rose-300 focus:ring-rose-100'
                    : isDark
                    ? 'border-slate-700 bg-slate-800 text-slate-100 focus:border-indigo-400 focus:ring-indigo-900'
                    : 'border-slate-200 bg-white focus:border-indigo-400 focus:ring-indigo-100'
                }`}
              />
              {addErrors.address_fa && (
                <p className="mt-1 text-[11px] font-medium text-rose-600 text-right">
                  ✕ {addErrors.address_fa}
                </p>
              )}
            </div>
          </div>
        </div>

        {/* Contact Persons (Legal only) */}
        {addForm.company_type && (
          <div
            className={`rounded-2xl border p-6 ${
              isDark ? 'border-slate-700' : 'border-slate-200'
            }`}
          >
            <div className="flex items-center justify-between mb-6">
              <h2
                className={`text-lg font-bold flex items-center gap-2 ${
                  isDark ? 'text-slate-100' : 'text-slate-900'
                }`}
              >
                👥 CONTACT PERSONS
                <span
                  className={`text-xs font-bold px-2 py-1 rounded-full ${
                    isDark
                      ? 'bg-indigo-900/50 text-indigo-300'
                      : 'bg-indigo-100 text-indigo-700'
                  }`}
                >
                  {addForm.contactPersons.length}
                </span>
              </h2>
              <button
                type="button"
                onClick={addContactPerson}
                className="flex items-center gap-1.5 text-sm font-semibold text-indigo-600 hover:text-indigo-700 transition-colors"
              >
                + ADD LIAISON
              </button>
            </div>

            {addErrors.contactPersons && (
              <div className="mb-4 rounded-lg border border-rose-200 bg-rose-50 p-3 text-xs font-medium text-rose-700">
                ✕ {addErrors.contactPersons}
              </div>
            )}

            <div className="space-y-3">
              {addForm.contactPersons.map((cp) => (
                <div
                  key={cp.id}
                  className={`grid grid-cols-12 gap-3 p-4 rounded-xl border ${
                    isDark
                      ? 'border-slate-700 bg-slate-800/50'
                      : 'border-slate-200 bg-slate-50/50'
                  }`}
                >
                  <div className="col-span-4">
                    <label
                      className={`mb-1 block text-[10px] font-semibold ${
                        isDark ? 'text-slate-300' : 'text-slate-600'
                      }`}
                    >
                      Liaison Name *
                    </label>
                    <input
                      value={cp.name}
                      onChange={(e) =>
                        updateContactPerson(cp.id, 'name', e.target.value)
                      }
                      className={`w-full rounded border px-2 py-1.5 text-xs focus:border-indigo-400 focus:outline-none ${
                        isDark
                          ? 'border-slate-700 bg-slate-800 text-slate-100'
                          : 'border-slate-200 bg-white'
                      }`}
                    />
                  </div>
                  <div className="col-span-3">
                    <label
                      className={`mb-1 block text-[10px] font-semibold ${
                        isDark ? 'text-slate-300' : 'text-slate-600'
                      }`}
                    >
                      Position/Rank
                    </label>
                    <input
                      value={cp.position}
                      onChange={(e) =>
                        updateContactPerson(cp.id, 'position', e.target.value)
                      }
                      className={`w-full rounded border px-2 py-1.5 text-xs focus:border-indigo-400 focus:outline-none ${
                        isDark
                          ? 'border-slate-700 bg-slate-800 text-slate-100'
                          : 'border-slate-200 bg-white'
                      }`}
                    />
                  </div>
                  <div className="col-span-3">
                    <label
                      className={`mb-1 block text-[10px] font-semibold ${
                        isDark ? 'text-slate-300' : 'text-slate-600'
                      }`}
                    >
                      Mobile *
                    </label>
                    <input
                      value={cp.mobile}
                      onChange={(e) =>
                        updateContactPerson(
                          cp.id,
                          'mobile',
                          e.target.value.replace(/\D/g, '')
                        )
                      }
                      className={`w-full rounded border px-2 py-1.5 text-xs font-mono focus:border-indigo-400 focus:outline-none ${
                        isDark
                          ? 'border-slate-700 bg-slate-800 text-slate-100'
                          : 'border-slate-200 bg-white'
                      }`}
                    />
                  </div>
                  <div className="col-span-2 flex items-end gap-1">
                    <div className="flex-1">
                      <label
                        className={`mb-1 block text-[10px] font-semibold ${
                          isDark ? 'text-slate-300' : 'text-slate-600'
                        }`}
                      >
                        Direct Email
                      </label>
                      <input
                        value={cp.email}
                        onChange={(e) =>
                          updateContactPerson(cp.id, 'email', e.target.value)
                        }
                        className={`w-full rounded border px-2 py-1.5 text-xs focus:border-indigo-400 focus:outline-none ${
                          isDark
                            ? 'border-slate-700 bg-slate-800 text-slate-100'
                            : 'border-slate-200 bg-white'
                        }`}
                      />
                    </div>
                    {addForm.contactPersons.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeContactPerson(cp.id)}
                        className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                      >
                        🗑️
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Actions */}
        <div
          className={`flex justify-end gap-3 pt-4 border-t ${
            isDark ? 'border-slate-700' : 'border-slate-100'
          }`}
        >
          <Button
            variant="ghost"
            onClick={() => {
              onClose();
              setDuplicateWarning(null);
            }}
          >
            Cancel
          </Button>
          <Button onClick={handleSave}>💾 Save Entity</Button>
        </div>
      </div>
    </Modal>
  );
}

// src/features/client-management/ui/ClientList.tsx

import { Button, Badge, Avatar } from '@design-system';
import { useTheme } from '@app/providers/ThemeProvider';
import { PermissionGuard } from '@shared/authorization/ui/PermissionGuard';
import type { Client, Contract } from '@entities/contract/types';
import { formatCurrency } from '@shared/lib/formatters';
import {
  calculateDaysProgress,
  calculateDaysLeft,
  getDaysUntilStart,
  getContractFinancialStatus,
  isExpiringSoon,
  getDaysProgressColor,
} from '@entities/contract/services/contractCalculations';

interface ClientListProps {
  clients: Client[];
  filteredClients: Client[];
  contracts: Contract[];
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  filter: 'ALL' | 'LEGAL' | 'INDIVIDUAL';
  setFilter: (filter: 'ALL' | 'LEGAL' | 'INDIVIDUAL') => void;
  clientCounts: { total: number; legal: number; individual: number };
  sortBy: 'name' | 'contracts' | 'value';
  setSortBy: (sort: 'name' | 'contracts' | 'value') => void;
  selectedClient: Client | null;
  setSelectedClient: (client: Client | null) => void;
  onAddClick: () => void;
  onExport: () => void;
  canCreate?: boolean;
  canExport?: boolean;
  canRead?: boolean;
}

export function ClientList({
  clients,
  filteredClients,
  contracts,
  searchQuery,
  setSearchQuery,
  filter,
  setFilter,
  clientCounts,
  sortBy,
  setSortBy,
  selectedClient,
  setSelectedClient,
  onAddClick,
  onExport,
  canCreate = true,
  canExport = true,
  canRead = true,
}: ClientListProps) {
  const { isDark } = useTheme();

  const handleClientClick = (client: Client) => {
    if (!canRead) return;
    setSelectedClient(client);
  };

  return (
    <div className={`col-span-1 lg:col-span-4 relative flex flex-col rounded-xl panel-3d overflow-hidden transition-all duration-300 ease-in-out max-h-[50vh] lg:max-h-none ${
      isDark ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200/70'}`}>
      
      {/* Header */}
      <div className={`relative z-10 border-b px-4 py-4 space-y-3 ${
        isDark ? 'border-slate-700 bg-slate-800/50' : 'border-slate-100 bg-slate-50/50'}`}>
        
        {/* Search & Sort */}
        <div className="flex items-center gap-3">
          <div className="relative flex-1">
            <span className={`absolute left-3 top-1/2 -translate-y-1/2 ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>🔍</span>
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by Name, ..."
              className="w-full rounded-lg py-2 pl-9 pr-8 text-sm input-themed"
            />
            {searchQuery && (
              <button 
                onClick={() => setSearchQuery('')} 
                className={`absolute right-3 top-1/2 -translate-y-1/2 ${isDark ? 'text-slate-500 hover:text-slate-300' : 'text-slate-400 hover:text-slate-600'}`}
              >
                ✕
              </button>
            )}
          </div>
          
          <div className="relative">
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as 'name' | 'contracts' | 'value')}
              className={`appearance-none text-xs rounded-md border pl-2 pr-6 py-2 font-medium focus:outline-none focus:ring-2 focus:ring-indigo-100 cursor-pointer ${
                isDark ? 'border-slate-700 bg-slate-800 text-slate-200 hover:bg-slate-700' : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-50'}`}
            >
              <option value="name">Name (A-Z)</option>
              <PermissionGuard elementId="client_stat_contracts" fallback={null}>
                <option value="contracts">Most Contracts</option>
              </PermissionGuard>
              <PermissionGuard elementId="client_stat_total_value" fallback={null}>
                <option value="value">Highest Value</option>
              </PermissionGuard>
            </select>
            <span className={`absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-[10px] ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>▼</span>
          </div>
        </div>

        {/* Filter Tabs */}
        <div className={`flex gap-1 rounded-lg border p-0.5 text-xs ${
          isDark ? 'border-slate-700 bg-slate-800' : 'border-slate-200 bg-white'}`}>
          {(['ALL', 'LEGAL', 'INDIVIDUAL'] as const).map((t) => {
            const count = t === 'ALL' ? clientCounts.total : t === 'LEGAL' ? clientCounts.legal : clientCounts.individual;
            return (
              <button
                key={t}
                onClick={() => setFilter(t)}
                className={`flex-1 rounded-md px-2 py-1.5 font-medium transition-all ${
                  filter === t
                    ? (isDark 
                        ? 'bg-indigo-600 text-white shadow-md shadow-indigo-500/30 border border-indigo-500'
                        : 'bg-indigo-50 text-indigo-700 border border-indigo-200')
                    : (isDark 
                        ? 'text-slate-400 hover:text-slate-200 hover:bg-slate-800'
                        : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50')
                }`}
              >
                {t === 'ALL' ? `All (${count})` : t === 'LEGAL' ? `🏢 Legal (${count})` : `👤 Individual (${count})`}
              </button>
            );
          })}
        </div>
      </div>

      {/* Client List */}
      <div className="flex-1 overflow-y-auto pb-24">
        {filteredClients.length === 0 ? (
          <div className="p-8 text-center">
            <div className="text-4xl mb-2">🔍</div>
            <p className={`text-sm ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>No clients found</p>
          </div>
        ) : (
          filteredClients.map((client) => (
            <div
              key={client.id}
              onClick={() => handleClientClick(client)}
              className={`flex items-center gap-3 px-4 py-3 border-b transition-colors ${
                canRead ? 'cursor-pointer' : 'cursor-not-allowed opacity-60'
              } ${
                isDark ? 'border-slate-700' : 'border-slate-100'
              } ${
                selectedClient?.id === client.id
                  ? (isDark ? 'bg-indigo-900/30 border-l-4 border-l-indigo-400' : 'bg-indigo-50 border-l-4 border-l-indigo-500')
                  : (isDark ? 'hover:bg-slate-800/60' : 'hover:bg-slate-50')
              }`}
            >
              <div className={`w-10 h-10 rounded-lg overflow-hidden border-2 shrink-0 ${
                isDark ? 'border-slate-600 bg-slate-800' : 'border-slate-200 bg-slate-50'
              } flex items-center justify-center`}>
                <Avatar name={client.name_en} gradient={client.logoColor} size="md"/>
              </div>
              <div className="flex-1 min-w-0">
                <div className={`text-sm font-medium truncate ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>{client.name_en}</div>
                <div className={`text-xs truncate ${isDark ? 'text-slate-300' : 'text-slate-600'}`} dir="rtl">{client.name_fa}</div>
                <div className="flex items-center gap-2 mt-1">
                  {filter === 'ALL' && (
                    <Badge tone={client.type === 'LEGAL' ? 'indigo' : 'violet'}>
                      {client.type === 'LEGAL' ? 'Legal' : 'Individual'}
                    </Badge>
                  )}
                  <PermissionGuard elementId="client_stat_contracts" fallback={null}>
                    {(() => {
                      const realCount = contracts.filter(c => c.client_id === client.id).length;
                      return (
                        <Badge tone="slate" className="font-semibold text-[10px]">
                          {realCount} {realCount === 1 ? 'Agreement' : 'Agreements'}
                        </Badge>
                      );
                    })()}
                  </PermissionGuard>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Gradient Fade */}
      <div className={`absolute bottom-0 left-0 right-0 h-28 bg-gradient-to-t pointer-events-none z-10 ${
        isDark 
          ? 'from-slate-900 via-slate-900/95 to-slate-900/0'
          : 'from-white via-white/95 to-white/0'}`} />
      
      {/* Action Buttons */}
      <div className="absolute bottom-5 left-0 right-0 px-4 z-20 flex gap-2">
        <PermissionGuard elementId="client_btn_add" fallback={null}>
          <Button 
            variant="primary"
            size="md"
            onClick={onAddClick} 
            className={`flex-1 justify-center gap-2 transition-all duration-300 hover:-translate-y-0.5 ${
              isDark 
                ? 'border border-indigo-400/30 shadow-[0_8px_24px_rgba(99,102,241,0.4)] hover:shadow-[0_12px_32px_rgba(99,102,241,0.6)]'
                : 'shadow-lg shadow-indigo-500/20 hover:shadow-xl hover:shadow-indigo-500/30'}`}
          >
            <span>➕</span> Add New Client
          </Button>
        </PermissionGuard>

        <PermissionGuard elementId="client_btn_export" fallback={null}>
          <Button
            variant="secondary"
            size="md"
            onClick={onExport}
            className={`transition-all duration-300 hover:-translate-y-0.5 ${
              isDark 
                ? 'border border-slate-700 shadow-[0_8px_24px_rgba(0,0,0,0.3)] hover:shadow-[0_12px_32px_rgba(0,0,0,0.5)]'
                : 'shadow-lg shadow-slate-300/50 hover:shadow-xl hover:shadow-slate-400/50'}`}
            title="Export to Excel"
          >
            📥
          </Button>
        </PermissionGuard>
      </div>
    </div>
  );
}

// src/features/client-management/ui/ContractDetailsModal.tsx

import { useMemo } from 'react';
import { Button, Badge, Card, Modal } from '@design-system';
import { useTheme } from '@app/providers/ThemeProvider';
import type { Contract, TariffLine } from '@entities/contract/types';
import { contractTariffs } from '@data/mockData';
import { formatCurrency } from '@shared/lib/formatters';
import {
  calculateProgressFromTariffs,
  calculateInvoiceProgress,
  calculateDaysLeft,
  getProgressTextClass,
  getProgressBgClass,
  isExpiringSoon,
} from '@entities/contract/services/contractCalculations';

// 🔐 RBAC Imports
import { usePermission } from '@shared/authorization/hooks/usePermission';

interface ContractDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  contract: Contract | null;
}

export function ContractDetailsModal({
  isOpen,
  onClose,
  contract,
}: ContractDetailsModalProps) {
  const { isDark } = useTheme();
  
  // 🔐 RBAC: چک کردن دسترسی‌ها
  const { can, canAny } = usePermission();
  const canViewContract = canAny(['contract:read', 'contract:view_all', 'contract:view_own']);
  const canViewInvoices = canAny(['invoice:read', 'invoice:view_all', 'invoice:view_own']);
  const canViewTariffs = can('contract:read'); // tariff بخشی از قرارداد هست

  const tariffs = useMemo(() => {
    if (!contract) return [];
    return contractTariffs.filter((t) => t.contract_id === contract.id);
  }, [contract]);

  const daysLeft = useMemo(() => {
    if (!contract) return 0;
    return calculateDaysLeft(contract.end_date);
  }, [contract]);

  const workProgress = useMemo(() => {
    if (!contract) return 0;
    return calculateProgressFromTariffs(contract);
  }, [contract]);

  const invoiceProgress = useMemo(() => {
    if (!contract) return 0;
    return calculateInvoiceProgress(contract);
  }, [contract]);
  
  const expiringInfo = useMemo(() => {
    if (!contract) return { expiring: false, daysLeft: 0 };
    return isExpiringSoon(contract);
  }, [contract]);

  if (!contract) return null;

  // 🔐 RBAC: اگر دسترسی به قرارداد نداره، پیام Access Denied نشون بده
  if (!canViewContract) {
    return (
      <Modal
        isOpen={isOpen}
        onClose={onClose}
        title="Access Denied"
        size="md"
      >
        <div className="text-center py-8">
          <div className="text-6xl mb-4">🚫</div>
          <h3 className={`text-lg font-bold mb-2 ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>
            You Don't Have Permission
          </h3>
          <p className={`text-sm ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>
            You need <code className="px-2 py-1 rounded bg-slate-200 dark:bg-slate-700">contract:read</code> permission to view contract details.
          </p>
          <div className="mt-6">
            <Button onClick={onClose}>Close</Button>
          </div>
        </div>
      </Modal>
    );
  }

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Contract Details"
      size="lg"
    >
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-start justify-between">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Badge tone={contract.type === 'CONTRACT' ? 'indigo' : 'amber'}>
                {contract.type}
              </Badge>
              <Badge
                tone={contract.status === 'ACTIVE' ? 'emerald' : 'slate'}
              >
                {contract.status}
              </Badge>
              {expiringInfo.expiring && (
                <Badge tone="danger" className="gap-1 animate-pulse">
                  <span>⚠️</span>
                  <span>Expiring in {expiringInfo.daysLeft} days</span>
                </Badge>
              )}
            </div>
            <h2
              className={`text-lg font-bold ${
                isDark ? 'text-slate-100' : 'text-slate-900'
              }`}
            >
              {contract.contract_title}
            </h2>
            <div
              className={`text-sm mt-1 ${
                isDark ? 'text-slate-300' : 'text-slate-600'
              }`}
            >
              {contract.contract_no} • {contract.client_name}
            </div>
          </div>
          {/* 🔐 RBAC: Total Value فقط با دسترسی مالی */}
          {canViewInvoices && (
            <div className="text-right">
              <div
                className={`text-xs ${
                  isDark ? 'text-slate-300' : 'text-slate-600'
                }`}
              >
                Total Value
              </div>
              <div
                className={`text-xl font-bold ${
                  isDark ? 'text-slate-100' : 'text-slate-900'
                }`}
              >
                {formatCurrency(contract.total_value)}
              </div>
            </div>
          )}
        </div>

        {/* Progress Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* 🔐 RBAC: Work Progress - همیشه نمایش داده میشه (بخش قرارداد) */}
          <Card className="p-4 card-3d">
            <div
              className={`text-xs mb-1 ${
                isDark ? 'text-slate-300' : 'text-slate-600'
              }`}
            >
              Performed Work Progress
            </div>
            <div
              className={`text-lg font-bold ${getProgressTextClass(workProgress, isDark)}`}
            >
              {workProgress.toFixed(2)}%
            </div>
            <div
              className={`mt-2 h-1.5 rounded-full overflow-hidden ${
                isDark ? 'bg-slate-700' : 'bg-slate-200'
              }`}
            >
              <div
                className={`h-full rounded-full ${getProgressBgClass(workProgress, isDark)}`}
                style={{ width: `${Math.min(workProgress, 100)}%` }}
              />
            </div>
          </Card>

          {/* 🔐 RBAC: Invoice Progress - فقط با دسترسی مالی */}
          {canViewInvoices ? (
            <Card className="p-4 card-3d">
              <div
                className={`text-xs mb-1 ${
                  isDark ? 'text-slate-300' : 'text-slate-600'
                }`}
              >
                Invoice Progress of Performed Works
              </div>
              <div
                className={`text-lg font-bold ${getProgressTextClass(invoiceProgress, isDark)}`}
              >
                {invoiceProgress.toFixed(2)}%
              </div>
              <div
                className={`mt-2 h-1.5 rounded-full overflow-hidden ${
                  isDark ? 'bg-slate-700' : 'bg-slate-200'
                }`}
              >
                <div
                  className={`h-full rounded-full ${getProgressBgClass(invoiceProgress, isDark)}`}
                  style={{ width: `${Math.min(invoiceProgress, 100)}%` }}
                />
              </div>
            </Card>
          ) : (
            <Card className="p-4 card-3d opacity-50">
              <div
                className={`text-xs mb-1 ${
                  isDark ? 'text-slate-300' : 'text-slate-600'
                }`}
              >
                Invoice Progress
              </div>
              <div className={`text-lg font-bold ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>
                🔒 Locked
              </div>
              <div className={`text-xs mt-2 ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>
                Need invoice:read permission
              </div>
            </Card>
          )}

          {/* Time Remaining - همیشه نمایش داده میشه */}
          <Card className={`p-4 border ${
            expiringInfo.expiring
              ? isDark
                ? 'bg-rose-950/30 border-rose-700 animate-pulse shadow-lg shadow-rose-500/20'
                : 'bg-rose-50 border-rose-300 animate-pulse shadow-lg shadow-rose-500/20'
              : isDark
                ? 'bg-slate-800/50 border-slate-700'
                : 'bg-white border-slate-200'
          }`}>
            <div className={`text-xs mb-1 ${
              expiringInfo.expiring
                ? isDark ? 'text-rose-300' : 'text-rose-700'
                : isDark ? 'text-slate-300' : 'text-slate-600'
            }`}>
              {expiringInfo.expiring ? '⚠️ Time Remaining' : 'Time Remaining'}
            </div>
            {daysLeft < 0 ? (
              <div className={`text-lg font-bold ${
                expiringInfo.expiring
                  ? isDark ? 'text-rose-400' : 'text-rose-600'
                  : 'text-rose-600'
              }`}>
                {Math.abs(daysLeft)} days overdue
              </div>
            ) : daysLeft === 0 ? (
              <div className={`text-lg font-bold ${
                expiringInfo.expiring
                  ? isDark ? 'text-rose-400' : 'text-rose-600'
                  : 'text-amber-600'
              }`}>
                Today (Expires)
              </div>
            ) : (
              <div className={`text-lg font-bold ${
                expiringInfo.expiring
                  ? isDark ? 'text-rose-400' : 'text-rose-600'
                  : 'text-emerald-600'
              }`}>
                {daysLeft} days remaining
              </div>
            )}
          </Card>
        </div>

        {canViewTariffs ? (
          <div>
            <h3
              className={`text-sm font-semibold mb-3 ${
                isDark ? 'text-slate-100' : 'text-slate-900'
              }`}
            >
              Details
            </h3>
            {tariffs.length === 0 ? (
              <div
                className={`text-center py-8 text-sm ${
                  isDark ? 'text-slate-500' : 'text-slate-400'
                }`}
              >
                No tariff lines defined for this contract
              </div>
            ) : (
              <div
                className={`overflow-x-auto rounded-lg border ${
                  isDark ? 'border-slate-700' : 'border-slate-200'
                }`}
              >
                <table className="w-full text-left text-xs">
                  <thead
                    className={`${
                      isDark ? 'bg-slate-800 text-slate-400' : 'bg-slate-50 text-slate-500'
                    } text-[10px] uppercase tracking-wide`}
                  >
                    <tr>
                      <th className="px-3 py-2 font-medium">Description</th>
                      <th className="px-3 py-2 font-medium">Unit</th>
                      <th className="px-3 py-2 font-medium text-right">Rate</th>
                      <th className="px-3 py-2 font-medium text-center">
                        Total Performed Work
                      </th>
                      {/* 🔐 RBAC: ستون‌های مالی فقط با invoice:read */}
                      {canViewInvoices && (
                        <>
                          <th className="px-3 py-2 font-medium text-right">
                            Total Value of Performed Works
                          </th>
                          <th className="px-3 py-2 font-medium text-right">
                            Total Invoiced
                          </th>
                        </>
                      )}
                    </tr>
                  </thead>
                  <tbody
                    className={
                      isDark ? 'divide-y divide-slate-700' : 'divide-y divide-slate-100'
                    }
                  >
                    {tariffs.map((tariff) => {
                      const consumed = tariff.consumed_quantity ?? 0;
                      const progress = consumed;
                      const value =
                        consumed *
                        (typeof tariff.rate === 'string'
                          ? Number(tariff.rate.replace(/,/g, '')) || 0
                          : tariff.rate || 0);
                      const invoiced = (tariff as any).invoiced || 0;
                      return (
                        <tr
                          key={tariff.id}
                          className={
                            isDark ? 'hover:bg-slate-800/60' : 'hover:bg-slate-50/60'
                          }
                        >
                          <td
                            className={`px-3 py-2 font-medium ${
                              isDark ? 'text-slate-200' : 'text-slate-800'
                            }`}
                          >
                            {tariff.description}
                          </td>
                          <td className="px-3 py-2">
                            <Badge tone="indigo">
                              {tariff.unit.replace('_', ' ')}
                            </Badge>
                          </td>
                          <td className="px-3 py-2 text-right font-mono">
                            {formatCurrency(tariff.rate, contract.currency)}
                          </td>
                          <td className="px-3 py-2 text-center font-mono">
                            {progress}
                          </td>
                          {/* 🔐 RBAC: ستون‌های مالی فقط با invoice:read */}
                          {canViewInvoices && (
                            <>
                              <td className="px-3 py-2 text-right font-mono font-semibold">
                                {formatCurrency(value, contract.currency)}
                              </td>
                              <td className="px-3 py-2 text-right font-mono font-semibold text-indigo-600">
                                {formatCurrency(invoiced)}
                              </td>
                            </>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot
                    className={
                      isDark
                        ? 'bg-slate-800 border-t-2 border-slate-600'
                        : 'bg-slate-100 border-t-2 border-slate-300'
                    }
                  >
                    <tr>
                      <td
                        colSpan={canViewInvoices ? 3 : 3}
                        className={`px-3 py-2.5 text-sm font-bold text-left uppercase tracking-wider ${
                          isDark ? 'text-slate-200' : 'text-slate-700'
                        }`}
                      >
                        💰 Total
                      </td>
                      <td
                        className={`px-3 py-2.5 text-center font-mono font-bold ${
                          isDark ? 'text-slate-100' : 'text-slate-900'
                        }`}
                      ></td>
                      {/* 🔐 RBAC: Totals فقط با invoice:read */}
                      {canViewInvoices && (
                        <>
                          <td className="px-3 py-2.5 text-right font-mono font-bold text-emerald-700">
                            {formatCurrency(
                              tariffs.reduce(
                                (sum, t) =>
                                  sum +
                                  (t.consumed_quantity || 0) *
                                    (typeof t.rate === 'string'
                                      ? Number(t.rate.replace(/,/g, '')) || 0
                                      : t.rate || 0),
                                0
                              ),
                              contract.currency
                            )}
                          </td>
                          <td className="px-3 py-2.5 text-right font-mono font-bold text-indigo-700">
                            {formatCurrency(
                              tariffs.reduce(
                                (sum, t) => sum + ((t as any).invoiced || 0),
                                0
                              )
                            )}
                          </td>
                        </>
                      )}
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}
          </div>
        ) : (
          <div
            className={`rounded-lg border-2 border-dashed p-8 text-center ${
              isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-300 bg-slate-50'
            }`}
          >
            <div className="text-4xl mb-3">🔒</div>
            <h4 className={`text-sm font-semibold mb-2 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
              Tariff Details Locked
            </h4>
            <p className={`text-xs ${isDark ? 'text-slate-400' : 'text-slate-600'}`}>
              You need <code className="px-2 py-1 rounded bg-slate-200 dark:bg-slate-700">contract:read</code> permission to view tariff details.
            </p>
          </div>
        )}
      </div>
    </Modal>
  );
}

// src/features/contract-management/ui/ContractDetails.tsx

import { useMemo } from 'react';
import { Button, Badge, Card } from '@design-system';
import { useTheme } from '@app/providers/ThemeProvider';
import { usePermission } from '@shared/authorization/hooks/usePermission';
import type { Contract, TariffLine } from '@entities/contract/types';
import { contractTariffs } from '@data/mockData';
import { formatCurrency } from '@shared/lib/formatters';
import {
  calculateProgressFromTariffs,
  calculateInvoiceProgress,
  calculateDaysProgress,
  calculateDaysLeft,
  getDaysUntilStart,
  getContractFinancialStatus,
  getAdjustmentReminder,
  isExpiringSoon,
  getProgressColor,
  getProgressTextClass,
  getProgressTextColor,
  getDaysProgressColor,
  getInvoicedPercentage,
} from '@entities/contract/services/contractCalculations';

interface ContractDetailsProps {
  contract: Contract | null;
  onClose: () => void;
  onEdit: () => void;
  onRequestComplete: (contract: Contract) => void;
  userRole: 'admin' | 'user';
  // 🔐 RBAC: اضافه شدن permission props
  canUpdate?: boolean;
  canApprove?: boolean;
  canDelete?: boolean;
  canRead?: boolean;
}

export function ContractDetails({
  contract,
  onClose,
  onEdit,
  onRequestComplete,
  userRole,
  canUpdate = true,   // 🔐 RBAC
  canApprove = true,  // 🔐 RBAC
  canDelete = true,   // 🔐 RBAC
  canRead = true,     // 🔐 RBAC
}: ContractDetailsProps) {
  const { isDark } = useTheme();
  
  // 🔐 RBAC: چک کردن دسترسی به مالی
  const { canAny } = usePermission();
  const canViewFinancial = canAny(['contract:read', 'contract:view_all', 'contract:view_own']);

  const selectedTariffs = useMemo(() => {
    if (!contract) return [];
    return contractTariffs.filter((t) => t.contract_id === contract.id);
  }, [contract]);

  const totalPerformedWork = useMemo(() => {
    if (!contract) return 0;
    return selectedTariffs.reduce((sum, t) => {
      const rate = typeof t.rate === 'string' ? Number(t.rate.replace(/,/g, '')) || 0 : (t.rate || 0);
      const consumed = t.consumed_quantity || 0;
      return sum + (rate * consumed);
    }, 0);
  }, [contract, selectedTariffs]);

  // حالت خالی - وقتی قراردادی انتخاب نشده
  if (!contract) {
    return (
      <div className={`flex-1 flex items-center justify-center relative overflow-hidden min-h-[600px] ${
        isDark
          ? 'bg-gradient-to-br from-slate-800 via-card to-indigo-950/30'
          : 'bg-gradient-to-br from-slate-50 via-white to-indigo-50/30'}`}>
        <div className="absolute inset-0 opacity-[0.03]" style={{
          backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='${isDark ? '%23ffffff' : '%23000000'}' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`
        }} />

        <div className="text-center z-10 relative">
          <div className="relative inline-block mb-8">
            <div className="absolute inset-0 rounded-full bg-gradient-to-br from-indigo-400 to-violet-500 blur-2xl opacity-40 animate-pulse"/>
            <div className={`relative inline-flex items-center justify-center w-44 h-44 rounded-full shadow-2xl shadow-indigo-500/30 border-4 ${
              isDark ? 'bg-slate-800 border-slate-700' : 'bg-white border-white'}`}>
              <img src="/images/logo.png" alt="ICS Logo" className="w-36 h-36 object-contain"/>
            </div>
          </div>

          <h2 className={`text-xl sm:text-2xl lg:text-3xl font-bold mb-3 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
            OFFSHORE & ENERGY DEPARTMENT INSPECTION PLATFORM
          </h2>
          <p className={`text-base max-w-md mx-auto leading-relaxed ${isDark ? 'text-secondary' : 'text-slate-500'}`}>
            Select a contract from the list to view details, tariffs, and progress information
          </p>

          <div className="flex items-center justify-center gap-6 mt-8">
            <div className="flex flex-col items-center gap-2">
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl ${isDark ? 'bg-indigo-900/50' : 'bg-indigo-100'}`}>📄</div>
              <span className={`text-xs font-medium ${isDark ? 'text-secondary' : 'text-slate-500'}`}>Contracts</span>
            </div>
            <div className="flex flex-col items-center gap-2">
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl ${isDark ? 'bg-emerald-900/50' : 'bg-emerald-100'}`}>📊</div>
              <span className={`text-xs font-medium ${isDark ? 'text-secondary' : 'text-slate-500'}`}>Tariffs</span>
            </div>
            <div className="flex flex-col items-center gap-2">
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl ${isDark ? 'bg-amber-900/50' : 'bg-amber-100'}`}>📈</div>
              <span className={`text-xs font-medium ${isDark ? 'text-secondary' : 'text-slate-500'}`}>Progress</span>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // حالت نمایش جزئیات قرارداد
  const financialStatus = getContractFinancialStatus(contract);
  const expiringInfo = isExpiringSoon(contract);
  const reminder = getAdjustmentReminder(contract);
  const daysUntilStart = getDaysUntilStart(contract.start_date);
  const daysLeft = calculateDaysLeft(contract.end_date);
  const isExpired = daysLeft < 0;
  const isFullyInvoiced = contract.invoiced >= contract.total_value;
  const needsFinancialReview = isExpired && !isFullyInvoiced;
  const notStarted = daysUntilStart > 0;

  return (
    <div className="flex-1 flex flex-col min-h-0 h-full overflow-hidden">
      {/* Header */}
      <div className={`border-b border-theme px-6 py-4 ${
        isDark
          ? 'bg-gradient-to-r from-slate-800 to-card'
          : 'bg-gradient-to-r from-slate-50 to-white'}`}>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xs font-semibold uppercase tracking-wider text-secondary">Contract Details</h2>
          <Button
            variant="ghost" size="sm" onClick={onClose}
            className={`transition-colors ${
              isDark ? 'text-muted hover:text-rose-400 hover:bg-rose-900/30' : 'text-muted hover:text-rose-600 hover:bg-rose-50'}`}
          >✕ Close Panel</Button>
        </div>
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <div className="flex items-center gap-4">
            <div className="flex h-12 w-12 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-violet-600 text-white text-lg font-bold">📄</div>
            <div>
              <h3 className="text-xl font-bold text-primary truncate min-w-0 max-w-[450px]" title={contract.contract_title}>
                {contract.contract_title}
              </h3>
              <p className="text-sm text-secondary font-mono">{contract.contract_no} • {contract.client_name}</p>
              <div className="flex items-center gap-2 mt-1.5">
                <Badge tone={contract.type === 'CONTRACT' ? 'indigo' : 'amber'}>
                  {contract.type === 'CONTRACT' ? '📄 Contract' : '📦 Work Order'}
                </Badge>
                {contract.status === 'COMPLETED' ? (
                  <Badge tone="slate">✓ Completed</Badge>
                ) : financialStatus === 'needs_review' ? (
                  <div className="flex items-center gap-2">
                    <Badge tone="amber" className="gap-1">
                      <span>⚠️</span>
                      <span>Needs Financial Review</span>
                    </Badge>
                    {/* 🔐 RBAC: دکمه Mark as Completed فقط با canApprove */}
                    {canApprove && (
                      <Button
                        variant="outline" size="sm" onClick={() => onRequestComplete(contract)}
                        className={`gap-1 text-xs ${
                          isDark ? 'border-amber-600 text-amber-300 hover:bg-amber-900/30' : 'border-amber-300 text-amber-700 hover:bg-amber-50'}`}
                      >
                        <span>✓</span>
                        <span>Mark as Completed</span>
                      </Button>
                    )}
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <Badge tone="emerald">🟢 Active</Badge>
                    {expiringInfo.expiring && (
                      <Badge tone="danger" className="gap-1 animate-pulse">
                        <span>⚠️</span>
                        <span>Expiring in {expiringInfo.daysLeft} days</span>
                      </Badge>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
          {/* 🔐 RBAC: دکمه Edit فقط با canUpdate */}
          {canUpdate && (
            <Button
              variant="outline" size="md" onClick={onEdit}
              disabled={contract.status === 'COMPLETED' || financialStatus === 'completed'}
              className={`gap-2 shadow-sm ${
                (contract.status === 'COMPLETED' || financialStatus === 'completed')
                  ? 'opacity-50 cursor-not-allowed' : ''}`}
              title={
                (contract.status === 'COMPLETED' || financialStatus === 'completed')
                  ? 'Completed contracts cannot be edited' : 'Edit contract'}
            >
              <span>✏️</span> Edit
            </Button>
          )}
        </div>
      </div>

      {/* یادآوری تعدیل */}
      {reminder.show && (
        <div className={`rounded-lg border-2 p-4 ${
          reminder.mode === 'TBD' ? (isDark ? 'border-amber-600 bg-amber-950/40' : 'border-amber-400 bg-amber-50')
            : (isDark ? 'border-indigo-600 bg-indigo-950/40' : 'border-indigo-400 bg-indigo-50')
        }`}>
          <div className="flex items-start gap-3">
            <div className="text-2xl">{reminder.mode === 'TBD' ? '⏳' : '📊'}</div>
            <div className="flex-1">
              <h4 className={`text-sm font-bold mb-1 ${
                reminder.mode === 'TBD' ? (isDark ? 'text-amber-200' : 'text-amber-900')
                  : (isDark ? 'text-indigo-200' : 'text-indigo-900')
              }`}>
                Price Adjustment Reminder
              </h4>
              <p className={`text-xs mb-2 ${
                reminder.mode === 'TBD' ? (isDark ? 'text-amber-300' : 'text-amber-800')
                  : (isDark ? 'text-indigo-300' : 'text-indigo-800')
              }`}>
                {reminder.mode === 'TBD' ? `Adjustment percentage needs to be determined. Effective date: ${reminder.effectiveDate}`
                  : `Adjustment will be applied. Effective date: ${reminder.effectiveDate}`
                }
              </p>
              <div className="flex items-center gap-4 text-xs">
                <div>
                  <span className={isDark ? 'text-slate-400' : 'text-slate-600'}>Days until effective: </span>
                  <span className={`font-bold ${
                    reminder.daysUntil <= 7 ? 'text-rose-500' :
                    reminder.daysUntil <= 15 ? 'text-amber-500' : 'text-emerald-500'}`}>
                    {reminder.daysUntil} days
                  </span>
                </div>
                {reminder.mode === 'FIXED' && reminder.percentage > 0 && (
                  <div>
                    <span className={isDark ? 'text-slate-400' : 'text-slate-600'}>Percentage: </span>
                    <span className="font-bold text-indigo-500">{reminder.percentage}%</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* محتوای قابل اسکرول */}
      <div className="flex-1 overflow-y-auto p-6 min-h-0">
        <div className="space-y-6">
          {/* اطلاعات قرارداد */}
          <div className={`rounded-lg border border-theme p-4 bg-muted/30`}>
            <h3 className="text-sm font-semibold text-primary mb-3 flex items-center gap-2">📋 Contract Information</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 lg:gap-4 text-sm">
              <div>
                <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Internal Contract No.</div>
                <div className="font-mono text-xs text-primary">{contract.contract_no}</div>
              </div>
              <div>
                <div className="text-[10px] uppercase text-secondary font-semibold mb-1">External Contract No.</div>
                <div className="font-mono text-xs text-primary">{contract.external_contract_no || '—'}</div>
              </div>
              <div>
                <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Currency</div>
                <div className="text-xs text-primary">{contract.currency}</div>
              </div>
              <div>
                <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Start Date</div>
                <div className="text-xs text-primary">{contract.start_date}</div>
              </div>
              <div>
                <div className="text-[10px] uppercase text-secondary font-semibold mb-1">End Date</div>
                <div className="text-xs text-primary">{contract.end_date}</div>
              </div>
              
              {/* 🔐 RBAC: اطلاعات مالی فقط با canViewFinancial */}
              {canViewFinancial ? (
                <>
                  <div>
                    <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Total Value</div>
                    <div className="text-xs font-semibold text-accent-emerald">{formatCurrency(contract.total_value, contract.currency)}</div>
                  </div>
                  <div>
                    <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Total Performed Works</div>
                    <div className="text-xs font-semibold text-accent-emerald">{formatCurrency(totalPerformedWork, contract.currency)}</div>
                  </div>
                  <div>
                    <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Invoiced</div>
                    <div className="text-xs font-semibold text-accent-indigo">
                      {formatCurrency(selectedTariffs.reduce((sum, t) => sum + ((t as any).invoiced || 0), 0))}
                    </div>
                  </div>
                  <div>
                    <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Not Invoiced</div>
                    <div className="text-xs font-semibold text-accent-rose">
                      {(() => {
                        const totalInvoiced = selectedTariffs.reduce((sum, t) => sum + ((t as any).invoiced || 0), 0);
                        const notInvoiced = Math.max(0, totalPerformedWork - totalInvoiced);
                        return formatCurrency(notInvoiced, contract.currency);
                      })()}
                    </div>
                  </div>
                </>
              ) : (
                <div className="col-span-full">
                  <div className="text-[10px] uppercase text-secondary font-semibold mb-1">Financial Information</div>
                  <div className="text-xs text-slate-400 italic">🔒 Locked - Need financial access permission</div>
                </div>
              )}
            </div>
          </div>

          {/* کارت‌های پیشرفت */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 lg:gap-4">
            <Card className={`rounded-lg border p-4 ${isDark ? 'border-slate-500 bg-slate-800/30' : 'border-slate-200'}`}>
              <div className="text-xs text-secondary">Total Performed Work (%)</div>
              {(() => {
                const workProgress = calculateProgressFromTariffs(contract);
                return (
                  <>
                    <div className={`text-lg font-bold ${getProgressTextClass(workProgress)}`}>
                      {workProgress.toFixed(2)}%
                    </div>
                    <div className={`mt-2 h-1.5 rounded-full overflow-hidden ${isDark ? 'bg-slate-700' : 'bg-slate-200'}`}>
                      <div
                        className={`h-full rounded-full ${getProgressColor(workProgress)}`}
                        style={{ width: `${Math.min(workProgress, 100)}%` }}
                      />
                    </div>
                  </>
                );
              })()}
            </Card>

            {/* 🔐 RBAC: کارت Invoiced فقط با canViewFinancial */}
            {canViewFinancial ? (
              <Card className={`rounded-lg border p-4 ${isDark ? 'border-slate-500 bg-slate-800/30' : 'border-slate-200'}`}>
                <div className="text-xs text-secondary">Total Invoiced (%)</div>
                {(() => {
                  const spent = calculateInvoiceProgress(contract);
                  return (
                    <>
                      <div className={`text-lg font-bold ${getProgressTextColor(spent)}`}>
                        {spent.toFixed(1)}%
                        {spent > 100 && <span className="text-xs ml-1">(Over)</span>}
                      </div>
                      <div className={`mt-2 h-1.5 rounded-full overflow-hidden ${isDark ? 'bg-slate-700' : 'bg-slate-200'}`}>
                        <div
                          className={`h-full rounded-full ${getProgressColor(spent)}`}
                          style={{ width: `${Math.min(spent, 100)}%` }}
                        />
                      </div>
                    </>
                  );
                })()}
              </Card>
            ) : (
              <Card className={`rounded-lg border p-4 opacity-50 ${isDark ? 'border-slate-500 bg-slate-800/30' : 'border-slate-200'}`}>
                <div className="text-xs text-secondary">Total Invoiced (%)</div>
                <div className="text-lg font-bold text-slate-400">🔒 Locked</div>
                <div className="text-[10px] text-slate-400 mt-1">Need invoice:read permission</div>
              </Card>
            )}

            <Card className={`rounded-lg border p-4 ${isDark ? 'border-slate-500 bg-slate-800/30' : 'border-slate-200'}`}>
              {notStarted ? (
                <>
                  <div className="text-xs text-secondary">Status</div>
                  <div className="text-lg font-bold text-amber-600">⏳ Not Started</div>
                  <div className="text-[10px] text-amber-500 mt-0.5">Starts in {daysUntilStart} days</div>
                </>
              ) : contract.status === 'COMPLETED' ? (
                <>
                  <div className="text-xs text-secondary">Status</div>
                  <div className="text-lg font-bold text-slate-600">✓ Completed</div>
                </>
              ) : needsFinancialReview ? (
                <>
                  <div className="text-xs text-secondary mb-2">Financial Status</div>
                  <div className="text-lg font-bold text-amber-600 mb-2">⚠️ Needs Review</div>
                  {/* 🔐 RBAC: دکمه Mark as Completed فقط با canApprove */}
                  {canApprove ? (
                    <button
                      onClick={() => onRequestComplete(contract)}
                      className="w-full rounded-lg px-3 py-2 text-xs font-semibold transition-all bg-amber-500 text-white hover:bg-amber-600 shadow-sm cursor-pointer"
                    >
                      <span className="flex items-center justify-center gap-1.5">
                        <span>✓</span>
                        <span>Mark as Completed</span>
                      </span>
                    </button>
                  ) : (
                    <button
                      disabled
                      className={`w-full rounded-lg px-3 py-2 text-xs font-semibold transition-all ${
                        isDark ? 'bg-slate-700 text-slate-400 cursor-not-allowed opacity-60' : 'bg-slate-100 text-slate-400 cursor-not-allowed opacity-60'
                      }`}
                      title="Only managers can approve completion"
                    >
                      <span className="flex items-center justify-center gap-1.5">
                        <span>🔒</span>
                        <span>Manager Approval Required</span>
                      </span>
                    </button>
                  )}
                </>
              ) : daysLeft < 0 ? (
                <>
                  <div className="text-xs text-secondary">Status</div>
                  <div className="text-lg font-bold text-rose-600">{Math.abs(daysLeft)} days overdue</div>
                </>
              ) : daysLeft === 0 ? (
                <>
                  <div className="text-xs text-secondary">Time Remaining</div>
                  <div className="text-lg font-bold text-amber-600">Today (Expires)</div>
                </>
              ) : (
                <>
                  <div className="text-xs text-secondary">Time Remaining</div>
                  <div className="text-lg font-bold text-emerald-600">{daysLeft} days remaining</div>
                </>
              )}
            </Card>
          </div>

          {/* 🔐 RBAC: جدول تعرفه‌ها فقط با canViewFinancial */}
          {canViewFinancial ? (
            <div>
              <h3 className="text-sm font-semibold text-primary mb-3">
                Tariff Lines & Consumption ({selectedTariffs.length})
              </h3>
              {selectedTariffs.length === 0 ? (
                <div className="text-center py-8 text-muted text-sm">
                  No tariff lines defined for this contract
                </div>
              ) : (
                <div className={`overflow-x-auto rounded-lg border border-theme`}>
                  <table className="w-full text-left text-xs">
                    <thead className={`bg-muted text-[9px] uppercase tracking-wide text-secondary`}>
                      <tr>
                        <th className="px-3 py-2 font-medium">Description</th>
                        <th className="px-3 py-2 font-medium">Unit</th>
                        <th className="px-3 py-2 font-medium text-right">Rate</th>
                        <th className="px-3 py-2 font-medium text-center">Performed Work</th>
                        <th className="px-3 py-2 font-medium text-right">Total Value of Performed Works</th>
                        <th className="px-3 py-2 font-medium text-right">Total Invoiced</th>
                      </tr>
                    </thead>
                    <tbody className={isDark ? 'divide-y divide-slate-700' : 'divide-y divide-slate-100'}>
                      {selectedTariffs.map((tariff) => {
                        const progress = tariff.consumed_quantity ?? 0;
                        const value = (tariff.consumed_quantity ?? 0) * (typeof tariff.rate === 'string' ? Number(tariff.rate.replace(/,/g, '')) || 0 : (tariff.rate || 0));
                        const invoiced = (tariff as any).invoiced || 0;
                        return (
                          <tr key={tariff.id} className={isDark ? 'hover:bg-muted/60' : 'hover:bg-muted/60'}>
                            <td className="px-3 py-2 font-medium text-primary">{tariff.description}</td>
                            <td className="px-3 py-2 text-[9px]">
                              <Badge tone="indigo">{tariff.unit.replace('_', '')}</Badge>
                            </td>
                            <td className="px-3 py-2 text-right font-mono">{formatCurrency(tariff.rate, contract.currency)}</td>
                            <td className="px-3 py-2 text-center font-mono">{tariff.consumed_quantity ?? 0}</td>
                            <td className="px-3 py-2 text-right font-mono font-semibold text-accent-emerald">
                              {formatCurrency(value, contract.currency)}
                            </td>
                            <td className="px-3 py-2 text-right font-mono font-semibold text-accent-indigo">
                              {formatCurrency(invoiced)}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                    <tfoot className={isDark ? 'bg-muted border-t-2 border-slate-600' : 'bg-slate-100 border-t-2 border-slate-300'}>
                      <tr>
                        <td colSpan={3} className="px-3 py-2.5 text-sm font-bold text-left uppercase tracking-wider text-primary">💰 Total</td>
                        <td className="px-3 py-2.5 text-center font-mono font-bold text-primary"></td>
                        <td className="px-3 py-2.5 text-right font-mono font-bold text-accent-emerald">
                          {formatCurrency(selectedTariffs.reduce((sum, t) => {
                            const rate = typeof t.rate === 'string' ? Number(t.rate.replace(/,/g, '')) || 0 : (t.rate || 0);
                            return sum + ((t.consumed_quantity || 0) * rate);
                          }, 0))}
                        </td>
                        <td className="px-3 py-2.5 text-right font-mono font-bold text-accent-indigo">
                          {formatCurrency(selectedTariffs.reduce((sum, t) => sum + ((t as any).invoiced || 0), 0))}
                        </td>
                      </tr>
                    </tfoot>
                  </table>
                </div>
              )}
            </div>
          ) : (
            <div className={`rounded-lg border-2 border-dashed p-8 text-center ${
              isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-300 bg-slate-50'
            }`}>
              <div className="text-4xl mb-3">🔒</div>
              <h4 className={`text-sm font-semibold mb-2 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
                Tariff Details Locked
              </h4>
              <p className={`text-xs ${isDark ? 'text-slate-400' : 'text-slate-600'}`}>
                You need financial access permission to view tariff details.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// src/features/contract-management/ui/ContractForm.tsx
// 🔐 RBAC: دسترسی‌ها بر اساس نقش کاربر

import { useState, useEffect } from 'react';
import { Button, Modal } from '@design-system';
import { useTheme } from '@app/providers/ThemeProvider';
import { usePermission } from '@shared/authorization/hooks/usePermission';
import { showToast } from '@shared/ui/ToastContainer';
import { JalaaliDatePicker } from '@shared/ui/JalaaliDatePicker';
import { ClientSelectorModal } from '@entities/client/ui/ClientSelectorModal';
import { ContractAttachmentsEditor } from '@entities/contract/ui/ContractAttachmentsEditor';
import { TariffEditor } from '@entities/contract/ui/TariffEditor';
import type { Contract, TariffLine, Adjustment, ContractModification, Guarantee, ContractAttachment } from '@entities/contract/types';
import { formatCurrency } from '@shared/lib/formatters';
import {
  formatNumberInput,
  parseNumberInput,
  getNextJalaaliYearStart,
} from '@entities/contract/services/contractCalculations';
import * as jalaali from 'jalaali-js';

interface ContractFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (formData: any) => void;
  initialData?: Partial<Contract>;
  mode: 'add' | 'edit';
  typeFilter: 'ALL' | 'CONTRACT' | 'WORK_ORDER';
  contracts: Contract[];
  generateContractNo: (type: 'CONTRACT' | 'WORK_ORDER', contracts: Contract[]) => string;
  onNavigateToClients: () => void;
  // 🔐 RBAC: اضافه شدن permission props
  canCreate?: boolean;
  canUpdate?: boolean;
}

export function ContractForm({
  isOpen,
  onClose,
  onSave,
  initialData,
  mode,
  typeFilter,
  contracts,
  generateContractNo,
  onNavigateToClients,
  canCreate = true,   // 🔐 RBAC
  canUpdate = true,   // 🔐 RBAC
}: ContractFormProps) {
  const { isDark } = useTheme();
  
  // 🔐 RBAC: چک کردن permission
  const { canAny } = usePermission();
  const canViewFinancial = canAny(['contract:read', 'contract:view_all', 'contract:view_own']);
  
  // 🔐 RBAC: محاسبه permission فعلی بر اساس mode
  const hasPermission = mode === 'add' ? canCreate : canUpdate;

  // 🔐 RBAC: اگر دسترسی نداره، مودال رو ببند
  useEffect(() => {
    if (isOpen && !hasPermission) {
      showToast('error', 'Access Denied', `You do not have permission to ${mode === 'add' ? 'create' : 'edit'} contracts`);
      onClose();
    }
  }, [isOpen, hasPermission, mode, onClose]);

  const [formData, setFormData] = useState({
    contract_no: initialData?.contract_no || generateContractNo(
      typeFilter === 'WORK_ORDER' ? 'WORK_ORDER' : 'CONTRACT',
      contracts
    ),
    external_contract_no: initialData?.external_contract_no || '',
    source_type: (initialData?.source_type || 'LETTER') as 'EMAIL' | 'LETTER',
    source_ref: initialData?.source_ref || '',
    source_file: initialData?.source_file || '',
    source_file_object: null as File | null,
    source_letter_date: initialData?.source_letter_date || '',
    source_letter_image: initialData?.source_letter_image || '',
    source_letter_image_object: null as File | null,
    source_letter_image_preview: initialData?.source_letter_image_preview || '',
    source_email_from: initialData?.source_email_from || '',
    source_email_date: initialData?.source_email_date || new Date().toISOString().split('T')[0],
    client_id: initialData?.client_id || '',
    contract_title: initialData?.contract_title || '',
    start_date: initialData?.start_date || '',
    end_date: initialData?.end_date || '',
    total_value: initialData?.total_value || 0,
    currency: initialData?.currency || 'IRR',
    status: (initialData?.status || 'ACTIVE') as 'ACTIVE' | 'COMPLETED',
    type: (typeFilter === 'WORK_ORDER' ? 'WORK_ORDER' : (initialData?.type || 'CONTRACT')) as 'CONTRACT' | 'WORK_ORDER',
    contract_count: initialData?.contract_count || 1,
    description: initialData?.description || '',
    tariffs: initialData?.tariffLines || [
      {
        id: '1',
        description: '',
        unit: 'MAN_DAY',
        rate: '',
        currency: 'IRR',
        total: 0,
        isLumpSum: false,
      },
    ] as TariffLine[],
    adjustment: {
      enabled: false,
      mode: 'FIXED' as 'FIXED' | 'TBD',
      percentage: 0,
      effective_date: '',
    } as Adjustment,
    contract_modification: {
      percentage: 0,
    } as ContractModification,
    guarantee: {
      has_guarantee: false,
      percentage: 0,
      type: 'BANK_GUARANTEE' as 'CHECK' | 'BANK_GUARANTEE' | 'PROMISSORY_NOTE' | 'CASH_BLOCK',
    } as Guarantee,
    good_performance_percentage: 10,
    insurance_deduction_percentage: 16.67,
    attachments: [] as ContractAttachment[],
    service_description: '' as 'TPI' | 'MWS' | 'TPER' | 'OTHER' | '',
  });

  const [errors, setErrors] = useState<any>({});

  const handleTypeChange = (type: 'CONTRACT' | 'WORK_ORDER') => {
    if (typeFilter !== 'ALL') return;
    setFormData({ ...formData, type });
  };

  const handleSmartStartDateChange = (newStartDate: string) => {
    const updatedForm = { ...formData, start_date: newStartDate };
    if (newStartDate && formData.end_date && formData.end_date < newStartDate) {
      updatedForm.end_date = newStartDate;
    }
    setFormData(updatedForm);
  };

  const handleSmartEndDateChange = (newEndDate: string) => {
    setFormData({ ...formData, end_date: newEndDate });
  };

  const validateForm = () => {
    const newErrors: any = {};

    if (formData.type === 'WORK_ORDER') {
      if (formData.source_type === 'LETTER') {
        if (!formData.source_ref.trim()) newErrors.source_ref = 'Letter number is required';
        if (!formData.source_letter_date) newErrors.source_letter_date = 'Letter date is required';
        if (!formData.source_letter_image) newErrors.source_letter_image = 'Letter image is required';
      } else if (formData.source_type === 'EMAIL') {
        if (!formData.source_email_from.trim()) newErrors.source_email_from = 'Email address is required';
      }
      if (!formData.client_id) newErrors.client_id = 'Client selection is required';
      if (!formData.contract_title.trim()) newErrors.contract_title = 'Work order title is required';
      if (!formData.tariffs || formData.tariffs.length === 0) {
        newErrors.tariffs = 'At least one tariff line is required';
      } else {
        const emptyTariff = formData.tariffs.find((t) => !t.description.trim() || !t.rate || parseNumberInput(t.rate as string) <= 0);
        if (emptyTariff) newErrors.tariffs = 'All tariff lines must have description and rate';
      }
    } else {
      if (!formData.contract_title.trim()) newErrors.contract_title = 'Contract title is required';
      if (!formData.client_id) newErrors.client_id = 'Client selection is required';
      if (!formData.start_date) newErrors.start_date = 'Start date is required';
      if (!formData.end_date) newErrors.end_date = 'End date is required';
      if (formData.start_date && formData.end_date && formData.end_date < formData.start_date) {
        newErrors.end_date = 'End date cannot be before start date';
      }
      if (formData.total_value <= 0) newErrors.total_value = 'Amount must be greater than zero';
      if (!formData.contract_count || formData.contract_count <= 0) newErrors.contract_count = 'Contract count is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // 🔐 RBAC: چک کردن permission قبل از submit
  const handleSave = () => {
    if (!hasPermission) {
      showToast('error', 'Access Denied', `You do not have permission to ${mode === 'add' ? 'create' : 'edit'} contracts`);
      return;
    }

    if (!validateForm()) return;
    onSave(formData);
    onClose();
  };

  // 🔐 RBAC: اگر دسترسی نداره، هیچی رندر نکن
  if (!hasPermission) {
    return null;
  }

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={mode === 'add' ? 'Add New Agreement' : 'Edit Contract'} size="lg">
      <div className="space-y-3">
        {/* Type Selector */}
        <div>
          <label className="mb-1.5 block text-xs font-semibold text-primary">
            Type *
            {typeFilter !== 'ALL' && (
              <span className={`ml-2 text-[10px] font-normal ${isDark ? 'text-amber-400' : 'text-amber-600'}`}>
                🔒 Locked to {typeFilter === 'CONTRACT' ? 'Contract' : 'Work Order'}
              </span>
            )}
          </label>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => handleTypeChange('CONTRACT')}
              disabled={typeFilter !== 'ALL'}
              className={`flex-1 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                formData.type === 'CONTRACT' ? 'bg-indigo-600 text-white shadow-md' : (isDark ? 'bg-muted text-secondary hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200')
              } ${typeFilter !== 'ALL' && formData.type !== 'CONTRACT' ? 'opacity-40 cursor-not-allowed' : ''}`}
            >
              📄 Contract
            </button>
            <button
              type="button"
              onClick={() => handleTypeChange('WORK_ORDER')}
              disabled={typeFilter !== 'ALL'}
              className={`flex-1 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                formData.type === 'WORK_ORDER' ? 'bg-amber-600 text-white shadow-md' : (isDark ? 'bg-muted text-secondary hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200')
              } ${typeFilter !== 'ALL' && formData.type !== 'WORK_ORDER' ? 'opacity-40 cursor-not-allowed' : ''}`}
            >
              📦 Work Order
            </button>
          </div>
        </div>

        {formData.type === 'CONTRACT' ? (
          <>
            {/* Contract Form Fields */}
            <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-200 bg-slate-50/50'} space-y-1`}>
              <div className="grid grid-cols-3 gap-4">
                <div>
                  <ClientSelectorModal
                    value={formData.client_id}
                    onChange={(clientId) => setFormData({ ...formData, client_id: clientId })}
                    onAddNew={onNavigateToClients}
                    error={errors.client_id}
                  />
                </div>
                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">Contract Title *</label>
                  <input
                    value={formData.contract_title}
                    onChange={(e) => setFormData({ ...formData, contract_title: e.target.value })}
                    className={`w-full rounded-lg px-3 py-2 text-sm input-themed ${errors.contract_title ? 'border-rose-300' : ''}`}
                    placeholder="e.g., South Pars Phase 22 — Inspection Services"
                  />
                  {errors.contract_title && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.contract_title}</p>}
                </div>
                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">Service Description *</label>
                  <select
                    value={formData.service_description}
                    onChange={(e) => setFormData({ ...formData, service_description: e.target.value as any })}
                    className={`w-full rounded-lg px-3 py-2 text-sm input-themed ${!formData.service_description ? 'text-muted' : ''}`}
                  >
                    <option value="">Select service type...</option>
                    <option value="TPI">🔍 TPI - Third Party Inspection</option>
                    <option value="MWS">🔧 MWS - Marine Warranty Survey</option>
                    <option value="TPER">📊 TPER - Technical Performance Evaluation Report</option>
                    <option value="OTHER">📋 Other</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Dates and Value */}
            <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-200 bg-slate-50/50'}`}>
              <div className="grid grid-cols-4 gap-4">
                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">Start Date *</label>
                  <JalaaliDatePicker
                    value={formData.start_date}
                    onChange={(date) => {
                      let effectiveDate = formData.adjustment.effective_date;
                      if (formData.adjustment.enabled && !effectiveDate && date) {
                        effectiveDate = getNextJalaaliYearStart(date);
                      }
                      setFormData({
                        ...formData,
                        start_date: date,
                        adjustment: { ...formData.adjustment, effective_date: effectiveDate }
                      });
                    }}
                    placeholder="Select start date"
                  />
                  {errors.start_date && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.start_date}</p>}
                </div>
                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">End Date *</label>
                  <JalaaliDatePicker
                    value={formData.end_date}
                    onChange={handleSmartEndDateChange}
                    minDate={formData.start_date}
                    placeholder={formData.start_date ? 'Select end date' : 'Select start date first'}
                    disabled={!formData.start_date}
                  />
                  {errors.end_date && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.end_date}</p>}
                </div>
                
                {/* 🔐 RBAC: فیلدهای مالی فقط با دسترسی */}
                {canViewFinancial ? (
                  <>
                    <div>
                      <label className="mb-1.5 block text-xs font-semibold text-primary">Total Value *</label>
                      <input
                        type="text"
                        inputMode="numeric"
                        value={formData.total_value ? formatNumberInput(String(formData.total_value)) : ''}
                        onChange={(e) => setFormData({ ...formData, total_value: parseNumberInput(e.target.value) })}
                        className={`w-full rounded-lg px-3 py-2 text-sm font-mono text-right input-themed ${errors.total_value ? 'border-rose-300' : ''}`}
                        placeholder="0"
                      />
                      {errors.total_value && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.total_value}</p>}
                    </div>
                    <div>
                      <label className="mb-1.5 block text-xs font-semibold text-primary">Currency</label>
                      <select
                        value={formData.currency}
                        onChange={(e) => setFormData({ ...formData, currency: e.target.value })}
                        className="w-full rounded-lg px-3 py-2 text-sm input-themed"
                      >
                        <option value="IRR">IRR</option>
                        <option value="USD">USD</option>
                        <option value="EUR">EUR</option>
                      </select>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="col-span-2">
                      <label className="mb-1.5 block text-xs font-semibold text-primary">Financial Information</label>
                      <div className="w-full rounded-lg border-2 border-dashed border-slate-400 bg-slate-100 dark:bg-slate-800/30 py-2.5 px-3 text-sm text-slate-500 italic text-center">
                        🔒 Locked - Need financial access permission
                      </div>
                    </div>
                  </>
                )}
              </div>
            </div>

            {/* 🔐 RBAC: ردیف‌های تعرفه فقط با دسترسی مالی */}
            {canViewFinancial ? (
              <TariffEditor
                tariffs={formData.tariffs}
                onChange={(tariffs) => setFormData({ ...formData, tariffs })}
                error={errors.tariffs}
                showTotals={false}
              />
            ) : (
              <div className={`rounded-lg border-2 border-dashed p-8 text-center ${
                isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-300 bg-slate-50'
              }`}>
                <div className="text-4xl mb-3">🔒</div>
                <h4 className={`text-sm font-semibold mb-2 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
                  Tariff Editor Locked
                </h4>
                <p className={`text-xs ${isDark ? 'text-slate-400' : 'text-slate-600'}`}>
                  You need financial access permission to edit tariffs.
                </p>
              </div>
            )}

            {/* Contract Numbers */}
            <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-200 bg-slate-50/50'}`}>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">Internal Contract No. (ICS)</label>
                  <div className={`w-full rounded-lg border border-theme bg-card py-2.5 px-3 text-sm font-mono font-semibold text-primary`}>
                    {formData.contract_no}
                  </div>
                  <p className="text-[10px] text-secondary mt-1">Auto-generated, Unique per ICS Department</p>
                </div>
                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">External Contract No (Optional)</label>
                  <input
                    value={formData.external_contract_no}
                    onChange={(e) => setFormData({ ...formData, external_contract_no: e.target.value })}
                    className={`w-full rounded-lg border border-theme bg-card py-2.5 px-3 text-sm font-mono font-semibold text-primary`}
                    placeholder="Client's Contract No."
                  />
                </div>
              </div>
            </div>

            {/* 🔐 RBAC: Financial & Legal Terms فقط با دسترسی مالی */}
            {canViewFinancial ? (
              <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-200 bg-slate-50/50'}`}>
                <h3 className={`text-sm font-bold mb-4 flex items-center gap-2 ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>
                  💼 Financial & Legal Terms
                </h3>

                <div className="space-y-2">
                  {/* Price Adjustment & Contract Modification */}
                  <div className="grid grid-cols-2 gap-3">
                    <div className={`rounded-lg border p-4 ${
                      formData.adjustment.enabled
                        ? (isDark ? 'border-indigo-700 bg-indigo-950/30' : 'border-indigo-200 bg-indigo-50/30')
                        : (isDark ? 'border-slate-700 bg-slate-800/20' : 'border-slate-200 bg-slate-50/20')
                    }`}>
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-2">
                          <span className="text-base">📊</span>
                          <h4 className={`text-sm font-semibold ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>
                            Price Adjustment
                          </h4>
                        </div>
                        <button
                          type="button"
                          onClick={() => {
                            const newEnabled = !formData.adjustment.enabled;
                            const effectiveDate = newEnabled && !formData.adjustment.effective_date && formData.start_date
                              ? getNextJalaaliYearStart(formData.start_date)
                              : formData.adjustment.effective_date;
                            setFormData({
                              ...formData,
                              adjustment: { ...formData.adjustment, enabled: newEnabled, effective_date: effectiveDate }
                            });
                          }}
                          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                            formData.adjustment.enabled ? 'bg-indigo-600' : (isDark ? 'bg-slate-700' : 'bg-slate-300')
                          }`}
                        >
                          <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                            formData.adjustment.enabled ? 'translate-x-6' : 'translate-x-1'}`} />
                        </button>
                      </div>

                      {formData.adjustment.enabled && (
                        <div className="space-y-3">
                          <div className={`rounded-lg border p-3 ${isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-200 bg-slate-50/30'}`}>
                            <label className={`mb-2 block text-[11px] font-semibold ${isDark ? 'text-slate-300' : 'text-slate-700'}`}>
                              Adjustment Mode
                            </label>
                            <div className="flex gap-2">
                              <button
                                type="button"
                                onClick={() => setFormData({ ...formData, adjustment: { ...formData.adjustment, mode: 'FIXED' } })}
                                className={`flex-1 px-3 py-2 rounded-lg text-xs font-semibold transition-all ${
                                  formData.adjustment.mode === 'FIXED' ? 'bg-indigo-600 text-white shadow-md' : (isDark ? 'bg-slate-700 text-slate-300 hover:bg-slate-600' : 'bg-slate-200 text-slate-600 hover:bg-slate-300')
                                }`}
                              >
                                ✅ Fixed
                              </button>
                              <button
                                type="button"
                                onClick={() => setFormData({ ...formData, adjustment: { ...formData.adjustment, mode: 'TBD', percentage: 0 } })}
                                className={`flex-1 px-3 py-2 rounded-lg text-xs font-semibold transition-all ${
                                  formData.adjustment.mode === 'TBD' ? 'bg-amber-600 text-white shadow-md' : (isDark ? 'bg-slate-700 text-slate-300 hover:bg-slate-600' : 'bg-slate-200 text-slate-600 hover:bg-slate-300')
                                }`}
                              >
                                ⏳ TBD
                              </button>
                            </div>
                          </div>

                          <div className="grid grid-cols-2 gap-3">
                            <div>
                              <label className={`mb-1 block text-[11px] font-semibold ${isDark ? 'text-slate-300' : 'text-slate-700'}`}>
                                Percentage (%)
                              </label>
                              <input
                                type="text"
                                inputMode="decimal"
                                value={formData.adjustment.percentage ? formatNumberInput(String(formData.adjustment.percentage)) : ''}
                                onChange={(e) => setFormData({
                                  ...formData,
                                  adjustment: { ...formData.adjustment, percentage: parseNumberInput(e.target.value) }
                                })}
                                disabled={formData.adjustment.mode === 'TBD'}
                                className={`w-full rounded-lg border px-3 py-2 text-sm font-mono text-right input-themed ${
                                  formData.adjustment.mode === 'TBD' ? 'opacity-50 cursor-not-allowed' : ''
                                }`}
                                placeholder="0.00"
                              />
                            </div>
                            <div>
                              <label className={`mb-1 block text-[11px] font-semibold ${isDark ? 'text-slate-300' : 'text-slate-700'}`}>
                                Effective Date
                              </label>
                              <JalaaliDatePicker
                                value={formData.adjustment.effective_date}
                                onChange={(date) => setFormData({
                                  ...formData,
                                  adjustment: { ...formData.adjustment, effective_date: date }
                                })}
                                placeholder="Select date"
                              />
                            </div>
                          </div>
                        </div>
                      )}
                    </div>

                    {/* Contract Modification */}
                    <div className={`rounded-lg border p-4 ${
                      formData.contract_modification.percentage > 0
                        ? (isDark ? 'border-indigo-700 bg-indigo-950/30' : 'border-indigo-200 bg-indigo-50/30')
                        : (isDark ? 'border-slate-700 bg-slate-800/20' : 'border-slate-200 bg-slate-50/20')
                    }`}>
                      <div className="flex items-center gap-2 mb-3">
                        <span className="text-base">🔄</span>
                        <h4 className={`text-sm font-semibold ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>
                          Contract Modification
                        </h4>
                      </div>

                      <div className="relative">
                        <input
                          type="text"
                          inputMode="decimal"
                          value={formData.contract_modification?.percentage ? formatNumberInput(String(formData.contract_modification.percentage)) : ''}
                          onChange={(e) => {
                            const raw = e.target.value.replace(/[^0-9.]/g, '');
                            const parts = raw.split('.');
                            const clean = parts.length > 2 ? parts[0] + '.' + parts.slice(1).join('') : raw;
                            setFormData({
                              ...formData,
                              contract_modification: { percentage: Number(clean) || 0 }
                            });
                          }}
                          className="w-full rounded-lg border px-3 py-2 pr-8 text-sm font-mono text-right input-themed"
                          placeholder="0"
                        />
                        <span className={`absolute right-3 top-1/2 -translate-y-1/2 text-xs font-semibold ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>%</span>
                      </div>

                      {formData.contract_modification.percentage > 0 && (
                        <div className={`mt-3 rounded-lg border p-3 ${isDark ? 'border-indigo-700 bg-indigo-950/30' : 'border-indigo-200 bg-indigo-50/50'}`}>
                          <div className="grid grid-cols-2 gap-2 text-xs">
                            <div className={`flex justify-between p-2 rounded ${isDark ? "bg-slate-800/50" : "bg-white/70"}`}>
                              <span className={isDark ? "text-slate-300" : "text-slate-600"}>💰 Ceiling:</span>
                              <span className="font-bold font-mono text-indigo-500">
                                {formData.total_value > 0 
                                  ? `+${formatCurrency((formData.total_value * formData.contract_modification.percentage) / 100, formData.currency)}`
                                  : "—"}
                              </span>
                            </div>
                            <div className={`flex justify-between p-2 rounded ${isDark ? 'bg-slate-800/50' : 'bg-white/70'}`}>
                              <span className={isDark ? 'text-slate-300' : 'text-slate-600'}>📅 Duration:</span>
                              <span className="font-bold font-mono text-indigo-500">
                                {formData.start_date && formData.end_date ? (() => {
                                  try {
                                    const [startJy, startJm, startJd] = formData.start_date.split('/').map(Number);
                                    const [endJy, endJm, endJd] = formData.end_date.split('/').map(Number);
                                    if (!startJy || !endJy) return '—';
                                    const startG = jalaali.toGregorian(startJy, startJm, startJd);
                                    const endG = jalaali.toGregorian(endJy, endJm, endJd);
                                    const startDate = new Date(startG.gy, startG.gm - 1, startG.gd);
                                    const endDate = new Date(endG.gy, endG.gm - 1, endG.gd);
                                    const totalDays = Math.ceil((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
                                    if (totalDays <= 0 || isNaN(totalDays)) return '—';
                                    const modifiedDays = Math.round((totalDays * formData.contract_modification.percentage) / 100);
                                    return `+${Math.abs(modifiedDays)} days`;
                                  } catch {
                                    return '—';
                                  }
                                })() : '—'}
                              </span>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Guarantee */}
                  <div className={`rounded-lg border p-4 ${
                    formData.guarantee.has_guarantee
                      ? (isDark ? 'border-emerald-700 bg-emerald-950/30' : 'border-emerald-200 bg-emerald-50/30')
                      : (isDark ? 'border-slate-700 bg-slate-800/20' : 'border-slate-200 bg-slate-50/20')
                  }`}>
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-2">
                        <span className="text-base">🏦</span>
                        <h4 className={`text-sm font-semibold ${isDark ? "text-slate-100" : "text-slate-900"}`}>
                          Performance Guarantee
                        </h4>
                        {formData.total_value <= 0 && (
                          <span className={`text-[10px] font-normal ${isDark ? "text-amber-400" : "text-amber-600"}`}>
                            ⚠️ Enter Total Value first
                          </span>
                        )}
                      </div>	
                      <button
                        type="button"
                        onClick={() => {
                          if (formData.total_value <= 0) return;
                          setFormData({
                            ...formData,
                            guarantee: { ...formData.guarantee, has_guarantee: !formData.guarantee.has_guarantee }
                          });
                        }}
                        disabled={formData.total_value <= 0}
                        className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                          formData.total_value <= 0
                            ? "opacity-40 cursor-not-allowed bg-slate-400"
                            : formData.guarantee.has_guarantee 
                              ? "bg-emerald-600"
                              : (isDark ? "bg-slate-700" : "bg-slate-300")
                        }`}
                        title={
                          formData.total_value <= 0 
                            ? "Enter Total Value first to enable guarantee"
                            : "Toggle performance guarantee"
                        }
                      >
                        <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                          formData.guarantee.has_guarantee ? "translate-x-6" : "translate-x-1"
                        }`} />
                      </button>
                    </div>

                    {formData.guarantee.has_guarantee && (
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label className={`mb-1 block text-[11px] font-semibold ${isDark ? 'text-slate-300' : 'text-slate-700'}`}>
                            Percentage (%)
                          </label>
                          <input
                            type="text"
                            inputMode="numeric"
                            value={formData.total_value ? formatNumberInput(String(formData.total_value)) : ""}
                            onChange={(e) => {
                              const newValue = parseNumberInput(e.target.value);
                              setFormData({
                                ...formData,
                                total_value: newValue,
                                guarantee: newValue <= 0 
                                  ? { ...formData.guarantee, has_guarantee: false, percentage: 0 }
                                  : formData.guarantee
                              });
                            }}
                            className="w-full rounded-lg border px-3 py-2 text-sm font-mono text-right input-themed"
                            placeholder="0.00"
                          />
                          {formData.total_value > 0 && formData.guarantee.percentage > 0 && (
                            <p className={`text-[10px] mt-1 font-semibold ${isDark ? 'text-emerald-400' : 'text-emerald-700'}`}>
                              ≈ {formatCurrency((formData.total_value * formData.guarantee.percentage) / 100, formData.currency)}
                            </p>
                          )}
                        </div>
                        <div>
                          <label className={`mb-1 block text-[11px] font-semibold ${isDark ? 'text-slate-300' : 'text-slate-700'}`}>
                            Guarantee Type
                          </label>
                          <select
                            value={formData.guarantee.type}
                            onChange={(e) => setFormData({
                              ...formData,
                              guarantee: { ...formData.guarantee, type: e.target.value as any }
                            })}
                            className="w-full rounded-lg border px-3 py-2 text-sm input-themed"
                          >
                            <option value="BANK_GUARANTEE">🏦 Bank Guarantee</option>
                            <option value="CHECK">📝 Check</option>
                            <option value="PROMISSORY_NOTE">📄 Promissory Note</option>
                            <option value="CASH_BLOCK">💰 Cash Block</option>
                          </select>
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Good Performance & Insurance */}
                  <div className="grid grid-cols-2 gap-3">
                    <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-700 bg-slate-800/20' : 'border-slate-200 bg-slate-50/20'}`}>
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-base">✅</span>
                        <h4 className={`text-sm font-semibold ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>Good Performance</h4>
                      </div>
                      <div className="relative">
                        <input
                          type="text"
                          inputMode="decimal"
                          value={formData.good_performance_percentage ? formatNumberInput(String(formData.good_performance_percentage)) : ''}
                          onChange={(e) => setFormData({ ...formData, good_performance_percentage: parseNumberInput(e.target.value) })}
                          className="w-full rounded-lg border px-3 py-2 pr-8 text-sm font-mono text-right input-themed"
                          placeholder="10.00"
                        />
                        <span className={`absolute right-3 top-1/2 -translate-y-1/2 text-xs font-semibold ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>%</span>
                      </div>
                    </div>

                    <div className={`rounded-lg border p-4 ${isDark ? 'border-slate-700 bg-slate-800/20' : 'border-slate-200 bg-slate-50/20'}`}>
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-base">🏥</span>
                        <h4 className={`text-sm font-semibold ${isDark ? 'text-slate-100' : 'text-slate-900'}`}>Insurance Deduction</h4>
                      </div>
                      <div className="relative">
                        <input
                          type="text"
                          inputMode="decimal"
                          value={formData.insurance_deduction_percentage ? formatNumberInput(String(formData.insurance_deduction_percentage)) : ''}
                          onChange={(e) => setFormData({ ...formData, insurance_deduction_percentage: parseNumberInput(e.target.value) })}
                          className="w-full rounded-lg border px-3 py-2 pr-8 text-sm font-mono text-right input-themed"
                          placeholder="16.67"
                        />
                        <span className={`absolute right-3 top-1/2 -translate-y-1/2 text-xs font-semibold ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>%</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className={`rounded-lg border-2 border-dashed p-8 text-center ${
                isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-300 bg-slate-50'
              }`}>
                <div className="text-4xl mb-3">🔒</div>
                <h4 className={`text-sm font-semibold mb-2 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
                  Financial & Legal Terms Locked
                </h4>
                <p className={`text-xs ${isDark ? 'text-slate-400' : 'text-slate-600'}`}>
                  You need financial access permission to edit financial terms.
                </p>
              </div>
            )}

            {/* Attachments */}
            <ContractAttachmentsEditor
              attachments={formData.attachments}
              onChange={(attachments) => setFormData({ ...formData, attachments })}
              isDark={isDark}
            />

            {/* Description */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-primary">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows={3}
                className="w-full rounded-lg px-3 py-2 text-sm input-themed"
                placeholder="Optional description..."
              />
            </div>
          </>
        ) : (
          <>
            {/* Work Order Form - همون قبلی بدون تغییر */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-primary">Source Type *</label>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => setFormData({ ...formData, source_type: 'LETTER' })}
                  className={`flex-1 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                    formData.source_type === 'LETTER' ? 'bg-emerald-600 text-white shadow-md' : (isDark ? 'bg-muted text-secondary hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200')
                  }`}
                >
                  📄 Letter
                </button>
                <button
                  type="button"
                  onClick={() => setFormData({ ...formData, source_type: 'EMAIL' })}
                  className={`flex-1 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                    formData.source_type === 'EMAIL' ? 'bg-blue-600 text-white shadow-md' : (isDark ? 'bg-muted text-secondary hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200')
                  }`}
                >
                  📧 Email
                </button>
              </div>
            </div>

            {formData.source_type === 'LETTER' ? (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="mb-1.5 block text-xs font-semibold text-primary">Letter Number *</label>
                    <input
                      value={formData.source_ref}
                      onChange={(e) => setFormData({ ...formData, source_ref: e.target.value })}
                      className="w-full rounded-lg bg-card px-3 py-2.5 text-sm font-mono input-themed"
                      placeholder="e.g., 1404/1234"
                    />
                    {errors.source_ref && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.source_ref}</p>}
                  </div>
                  <div>
                    <label className="mb-1.5 block text-xs font-semibold text-primary">Letter Date *</label>
                    <JalaaliDatePicker
                      value={formData.source_letter_date || ''}
                      onChange={(date) => setFormData({ ...formData, source_letter_date: date })}
                      placeholder="Select letter date"
                    />
                    {errors.source_letter_date && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.source_letter_date}</p>}
                  </div>
                </div>

                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">
                    Letter Image * <span className="text-rose-500">(Required)</span>
                  </label>
                  <div className="relative">
                    <input
                      type="file"
                      id="letter-image-input"
                      accept="image/*"
                      onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                          const preview = URL.createObjectURL(file);
                          setFormData({
                            ...formData,
                            source_letter_image: file.name,
                            source_letter_image_object: file,
                            source_letter_image_preview: preview,
                          });
                        }
                      }}
                      className="hidden"
                    />
                    <label
                      htmlFor="letter-image-input"
                      className={`flex items-center justify-between gap-2 w-full rounded-lg border-2 px-3 py-2.5 text-sm cursor-pointer transition-colors ${
                        formData.source_letter_image
                          ? (isDark ? 'border-emerald-600 bg-emerald-900/30 text-emerald-300 hover:bg-emerald-900/50' : 'border-emerald-400 bg-emerald-50 text-emerald-700 hover:bg-emerald-100')
                          : (isDark ? 'border-dashed border-slate-600 bg-muted text-secondary hover:border-indigo-500 hover:bg-slate-800' : 'border-dashed border-slate-300 bg-muted text-slate-600 hover:border-indigo-400 hover:bg-indigo-50')
                      }`}
                    >
                      {formData.source_letter_image ? (
                        <>
                          <div className="flex items-center gap-2 flex-1 min-w-0">
                            <span>🖼️</span>
                            <span className="truncate font-medium">{formData.source_letter_image}</span>
                          </div>
                          <div className="flex items-center gap-2 shrink-0">
                            {formData.source_letter_image_preview && (
                              <img src={formData.source_letter_image_preview} alt="Preview" className="h-8 w-8 object-cover rounded border border-slate-200" />
                            )}
                            <button
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                setFormData({
                                  ...formData,
                                  source_letter_image: '',
                                  source_letter_image_object: null,
                                  source_letter_image_preview: '',
                                });
                                const input = document.getElementById('letter-image-input') as HTMLInputElement;
                                if (input) input.value = '';
                              }}
                              className="p-1 text-rose-500 hover:text-rose-700 hover:bg-rose-100 rounded transition-colors"
                              title="Remove image"
                            >
                              ✕
                            </button>
                          </div>
                        </>
                      ) : (
                        <div className="flex items-center gap-2">
                          <span>📎</span>
                          <span>Click to attach letter image (JPG, PNG, PDF)</span>
                        </div>
                      )}
                    </label>
                  </div>
                  {errors.source_letter_image && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.source_letter_image}</p>}
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="mb-1.5 block text-xs font-semibold text-primary">From Email Address *</label>
                    <input
                      type="email"
                      value={formData.source_email_from || ''}
                      onChange={(e) => setFormData({ ...formData, source_email_from: e.target.value })}
                      className={`w-full rounded-lg bg-card px-3 py-2.5 text-sm font-mono input-themed ${errors.source_email_from ? 'border-rose-300' : ''}`}
                      placeholder="sender@example.com"
                    />
                    {errors.source_email_from && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.source_email_from}</p>}
                  </div>
                  <div>
                    <label className="mb-1.5 block text-xs font-semibold text-primary">Email Date</label>
                    <input
                      type="date"
                      value={formData.source_email_date || ''}
                      onChange={(e) => setFormData({ ...formData, source_email_date: e.target.value })}
                      className="w-full rounded-lg bg-card px-3 py-2.5 text-sm input-themed"
                    />
                  </div>
                </div>

                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-primary">Attach Email File</label>
                  <div className="relative">
                    <input
                      type="file"
                      id="email-file-input"
                      accept=".msg,.eml"
                      onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                          setFormData({
                            ...formData,
                            source_file: file.name,
                            source_file_object: file
                          });
                        }
                      }}
                      className="hidden"
                    />
                    <label
                      htmlFor="email-file-input"
                      className={`flex items-center justify-between gap-2 w-full rounded-lg border-2 px-3 py-2.5 text-sm cursor-pointer transition-colors ${
                        formData.source_file
                          ? (isDark ? 'border-emerald-600 bg-emerald-900/30 text-emerald-300 hover:bg-emerald-900/50' : 'border-emerald-400 bg-emerald-50 text-emerald-700 hover:bg-emerald-100')
                          : (isDark ? 'border-dashed border-slate-600 bg-muted text-secondary hover:border-indigo-500 hover:bg-slate-800' : 'border-dashed border-slate-300 bg-muted text-slate-600 hover:border-indigo-400 hover:bg-indigo-50')
                      }`}
                    >
                      {formData.source_file ? (
                        <>
                          <button
                            type="button"
                            onClick={(e) => {
                              e.preventDefault();
                              e.stopPropagation();
                              if (formData.source_file_object) {
                                const url = URL.createObjectURL(formData.source_file_object);
                                window.open(url, '_blank');
                              }
                            }}
                            className="flex items-center gap-2 flex-1 text-left hover:underline min-w-0"
                            title="Click to open email"
                          >
                            <span>📧</span>
                            <span className="truncate font-medium">{formData.source_file}</span>
                          </button>
                          <button
                            type="button"
                            onClick={(e) => {
                              e.preventDefault();
                              e.stopPropagation();
                              setFormData({ ...formData, source_file: '', source_file_object: null });
                              const input = document.getElementById('email-file-input') as HTMLInputElement;
                              if (input) input.value = '';
                            }}
                            className="shrink-0 p-1 text-rose-500 hover:text-rose-700 hover:bg-rose-100 rounded transition-colors"
                            title="Remove file"
                          >
                            ✕
                          </button>
                        </>
                      ) : (
                        <div className="flex items-center gap-2">
                          <span>📎</span>
                          <span>Click to attach (.msg, .eml)</span>
                        </div>
                      )}
                    </label>
                  </div>
                </div>
              </div>
            )}

            <ClientSelectorModal
              value={formData.client_id}
              onChange={(clientId) => setFormData({ ...formData, client_id: clientId })}
              onAddNew={onNavigateToClients}
              error={errors.client_id}
            />

            <div>
              <label className="mb-1.5 block text-xs font-semibold text-primary">Work Order Title *</label>
              <input
                value={formData.contract_title}
                onChange={(e) => setFormData({ ...formData, contract_title: e.target.value })}
                className={`w-full rounded-lg px-3 py-2 text-sm input-themed ${errors.contract_title ? 'border-rose-300' : ''}`}
                placeholder="Brief title of the work order"
              />
              {errors.contract_title && <p className="mt-1 text-[11px] font-medium text-rose-600">✕ {errors.contract_title}</p>}
            </div>

            {/* 🔐 RBAC: Tariff Editor فقط با دسترسی مالی */}
            {canViewFinancial ? (
              <TariffEditor
                tariffs={formData.tariffs}
                onChange={(tariffs) => setFormData({ ...formData, tariffs })}
                error={errors.tariffs}
                showTotals={false}
              />
            ) : (
              <div className={`rounded-lg border-2 border-dashed p-8 text-center ${
                isDark ? 'border-slate-700 bg-slate-800/30' : 'border-slate-300 bg-slate-50'
              }`}>
                <div className="text-4xl mb-3">🔒</div>
                <h4 className={`text-sm font-semibold mb-2 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
                  Tariff Editor Locked
                </h4>
                <p className={`text-xs ${isDark ? 'text-slate-400' : 'text-slate-600'}`}>
                  You need financial access permission to edit tariffs.
                </p>
              </div>
            )}

            <div>
              <label className="mb-1.5 block text-xs font-semibold text-primary">Description (Optional)</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows={3}
                className="w-full rounded-lg px-3 py-2 text-sm input-themed"
                placeholder="Additional details..."
              />
            </div>
          </>
        )}

        <div className={`flex justify-end gap-3 pt-4 border-t ${isDark ? 'border-slate-700' : 'border-slate-100'}`}>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSave}>💾 Save {formData.type === 'CONTRACT' ? 'Contract' : 'Work Order'}</Button>
        </div>
      </div>
    </Modal>
  );
}

// src/features/contract-management/ui/ContractList.tsx

import { Button, Badge } from '@design-system';
import { useTheme } from '@app/providers/ThemeProvider';
import { usePermission } from '@shared/authorization/hooks/usePermission';
import type { Contract } from '@entities/contract/types';
import { formatCurrency } from '@shared/lib/formatters';
import {
  calculateProgressFromTariffs,
  calculateDaysProgress,
  calculateDaysLeft,
  getDaysUntilStart,
  getContractFinancialStatus,
  isExpiringSoon,
  getDaysProgressColor,
} from '@entities/contract/services/contractCalculations';

interface ContractListProps {
  contracts: Contract[];
  filteredContracts: Contract[];
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  typeFilter: 'ALL' | 'CONTRACT' | 'WORK_ORDER';
  setTypeFilter: (type: 'ALL' | 'CONTRACT' | 'WORK_ORDER') => void;
  statusFilter: 'ALL' | 'ACTIVE' | 'NOT_STARTED' | 'NEEDS_REVIEW' | 'COMPLETED';
  setStatusFilter: (status: 'ALL' | 'ACTIVE' | 'NOT_STARTED' | 'NEEDS_REVIEW' | 'COMPLETED') => void;
  sortBy: 'date' | 'value' | 'status';
  setSortBy: (sort: 'date' | 'value' | 'status') => void;
  selectedContract: Contract | null;
  setSelectedContract: (contract: Contract) => void;
  onAddClick: () => void;
  onExport: () => void;
  // 🔐 RBAC: اضافه شدن permission props
  canCreate?: boolean;
  canExport?: boolean;
  canRead?: boolean;
}

export function ContractList({
  contracts,
  filteredContracts,
  searchQuery,
  setSearchQuery,
  typeFilter,
  setTypeFilter,
  statusFilter,
  setStatusFilter,
  sortBy,
  setSortBy,
  selectedContract,
  setSelectedContract,
  onAddClick,
  onExport,
  canCreate = true,   // 🔐 RBAC
  canExport = true,   // 🔐 RBAC
  canRead = true,     // 🔐 RBAC
}: ContractListProps) {
  const { isDark } = useTheme();
  
  // 🔐 RBAC: چک کردن دسترسی به مالی
  const { canAny } = usePermission();
  const canViewFinancial = canAny(['contract:read', 'contract:view_all', 'contract:view_own']);

  // 🔐 RBAC: Handler برای کلیک روی قرارداد
  const handleContractClick = (contract: Contract) => {
    if (!canRead) {
      return;
    }
    setSelectedContract(contract);
  };

  return (
    <div className={`col-span-1 lg:col-span-4 relative flex flex-col rounded-xl panel-3d overflow-hidden transition-all duration-300 ease-in-out max-h-[50vh] lg:max-h-none ${
      isDark ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200/70'}`}>
      {/* Header */}
      <div className={`relative z-10 border-b px-4 py-4 space-y-3 ${
        isDark ? 'border-slate-700 bg-slate-800/50' : 'border-slate-100 bg-slate-50/50'}`}>
        {/* Search & Sort */}
        <div className="flex items-center gap-3">
          <div className="relative flex-1">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted">🔍</span>
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by Contract No, ..."
              className="w-full rounded-lg py-2 pl-9 pr-8 text-sm input-themed"
            />
            {searchQuery && (
              <button onClick={() => setSearchQuery('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-primary">✕</button>
            )}
          </div>
          <div className="relative">
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as 'date' | 'value' | 'status')}
              className="appearance-none text-xs rounded-md pl-2 pr-6 py-2 font-medium cursor-pointer input-themed"
            >
              <option value="date">Latest First</option>
              {/* 🔐 RBAC: گزینه value فقط با دسترسی مالی */}
              {canViewFinancial && <option value="value">Highest Value</option>}
              <option value="status">By Status</option>
            </select>
            <span className="absolute right-2 top-1/2 -translate-y-1/2 text-muted pointer-events-none text-[10px]">▼</span>
          </div>
        </div>

        {/* Type Filter */}
        <div className={`flex gap-1 rounded-lg border p-0.5 text-xs ${
          isDark ? 'border-slate-700 bg-slate-800' : 'border-slate-200 bg-white'}`}>
          {(['ALL', 'CONTRACT', 'WORK_ORDER'] as const).map((t) => {
            const count = t === 'ALL' ? contracts.length : t === 'CONTRACT' ? contracts.filter(c => c.type === 'CONTRACT').length : contracts.filter(c => c.type === 'WORK_ORDER').length;
            return (
              <button
                key={t}
                onClick={() => setTypeFilter(t)}
                className={`flex-1 rounded px-1 py-1.5 font-medium transition-all whitespace-nowrap ${
                  typeFilter === t
                    ? (isDark 
                        ? 'bg-indigo-600 text-white shadow-md shadow-indigo-500/30 border border-indigo-500'
                        : 'bg-indigo-50 text-indigo-700 border border-indigo-200 shadow-sm')
                    : (isDark 
                        ? 'text-slate-400 hover:text-slate-200 hover:bg-slate-800'
                        : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50')
                }`}
              >
                {t === 'ALL' ? `All (${count})` : t === 'CONTRACT' ? `📄 (${count})` : `📦(${count})`}
              </button>
            );
          })}
        </div>

        {/* Status Filter */}
        <div className={`flex gap-1 rounded-lg border p-1 text-xs ${
          isDark ? 'border-slate-700 bg-slate-800' : 'border-slate-200 bg-white'}`}>
          {(['ALL', 'ACTIVE', 'NOT_STARTED', 'NEEDS_REVIEW', 'COMPLETED'] as const).map((t) => {
            const baseFiltered = typeFilter === 'ALL' ? contracts : contracts.filter(c => c.type === typeFilter);
            let count = 0;
            
            if (t === 'ALL') count = baseFiltered.length;
            else if (t === 'ACTIVE') count = baseFiltered.filter(c => getContractFinancialStatus(c) === 'active').length;
            else if (t === 'NOT_STARTED') count = baseFiltered.filter(c => getContractFinancialStatus(c) === 'not_started').length;
            else if (t === 'NEEDS_REVIEW') count = baseFiltered.filter(c => getContractFinancialStatus(c) === 'needs_review').length;
            else if (t === 'COMPLETED') count = baseFiltered.filter(c => getContractFinancialStatus(c) === 'completed').length;
            
            return (
              <button
                key={t}
                onClick={() => setStatusFilter(t)}
                className={`flex-1 rounded px-1 py-1.5 font-medium transition-all whitespace-nowrap ${
                  statusFilter === t
                    ? (isDark 
                        ? 'bg-emerald-600 text-white shadow-md shadow-emerald-500/30 border border-emerald-500'
                        : 'bg-emerald-50 text-emerald-700 border border-emerald-200 shadow-sm')
                    : (isDark 
                        ? 'text-slate-300 hover:text-slate-100 hover:bg-slate-700'
                        : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50')
                }`}
              >
                {t === 'ALL' ? `All (${count})` : 
                 t === 'ACTIVE' ? `🟢 (${count})` : 
                 t === 'NOT_STARTED' ? `⏳ (${count})` : 
                 t === 'NEEDS_REVIEW' ? `⚠️ (${count})` : 
                 `✓ (${count})`}
              </button>
            );
          })}
        </div>
      </div>

      {/* Contract List */}
      <div className="flex-1 overflow-y-auto pb-24">
        {filteredContracts.length === 0 ? (
          <div className="p-8 text-center">
            <div className="text-4xl mb-2">📄</div>
            <p className="text-sm text-secondary">No contracts found</p>
          </div>
        ) : (
          filteredContracts.map((contract) => {
            return (
              <div
                key={contract.id}
                onClick={() => handleContractClick(contract)}
                className={`flex flex-col gap-2 px-4 py-3 border-b border-theme transition-colors ${
                  canRead ? 'cursor-pointer' : 'cursor-not-allowed opacity-60'
                } ${
                  selectedContract?.id === contract.id
                    ? (isDark ? 'bg-indigo-900/30 border-l-4 border-l-indigo-400' : 'bg-indigo-50 border-l-4 border-l-indigo-500')
                    : (isDark ? 'hover:bg-muted' : 'hover:bg-muted')
                }`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <Badge tone={contract.type === 'CONTRACT' ? 'indigo' : 'amber'}>
                        {contract.type === 'CONTRACT' ? '📄 Contract' : '📦 Work Order'}
                      </Badge>
                      <span className="font-mono text-xs text-secondary">{contract.contract_no}</span>
                    </div>
                    <div className="text-sm font-medium text-primary truncate">{contract.contract_title}</div>
                    <div className="text-xs text-secondary truncate">{contract.client_name}</div>
                  </div>
                  {(() => {
                    const financialStatus = getContractFinancialStatus(contract);
                    const expiringInfo = isExpiringSoon(contract);
                    
                    if (contract.status === 'COMPLETED') {
                      return <Badge tone="slate">✓ Completed</Badge>;
                    }
                    
                    if (expiringInfo.expiring) {
                      return (
                        <Badge tone="danger" className="gap-1 animate-pulse">
                          <span>⚠️</span>
                          <span>Expiring Soon</span>
                        </Badge>
                      );
                    }
                    
                    if (financialStatus === 'not_started') {
                      return (
                        <Badge tone="amber" className="gap-1">
                          <span>⏳</span>
                          <span>Not Started</span>
                        </Badge>
                      );
                    }
                    
                    if (financialStatus === 'needs_review') {
                      return (
                        <Badge tone="amber" className="gap-1">
