type PermissionGroup = {
  label: string;
  icon: string;
  permissions: string[];
};

const permissionGroups: Record<string, PermissionGroup> =
  Object.fromEntries(
    ENTITIES.map(entity => [
      entity,
      {
        label: ENTITY_GROUPS[entity].label,
        icon: ENTITY_GROUPS[entity].icon,
        permissions: DEFAULT_ACTIONS.map(action => `${entity}:${action}`),
      },
    ])
  );

